const HTML = "<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow, noarchive\">\n<title>つむぎ 変更管理台帳</title>\n<style>:root{color-scheme:light dark}html,body{margin:0;padding:0}</style>\n<style>\n  :root{\n    --bg:#f7f8fb; --panel:#ffffff; --ink:#171a21; --ink-2:#5a6072; --ink-3:#8a90a2;\n    --line:#e7e9f0; --line-2:#eef0f6; --accent:#4b53c4; --accent-soft:#eceef9;\n    --bug:#d6455f; --bug-soft:#fbe9ec; --feat:#0f8f7e; --feat-soft:#e2f3ef;\n    --imp:#c07a15; --imp-soft:#f8efdd; --ops:#7b8194; --ops-soft:#eef0f4;\n    --crit:#c0392b; --focus:#4b53c4;\n    --mono:ui-monospace,\"SFMono-Regular\",Menlo,Consolas,monospace;\n    --jp:\"Hiragino Sans\",\"Hiragino Kaku Gothic ProN\",\"Yu Gothic\",\"Noto Sans JP\",\"Meiryo\",system-ui,sans-serif;\n  }\n  @media (prefers-color-scheme:dark){\n    :root{\n      --bg:#0f1116; --panel:#171a22; --ink:#e9ebf2; --ink-2:#a2a8bb; --ink-3:#71778a;\n      --line:#262a36; --line-2:#20242e; --accent:#8b93ee; --accent-soft:#20233a;\n      --bug:#f0879a; --bug-soft:#2c1a20; --feat:#5fcdb6; --feat-soft:#152621;\n      --imp:#e0ad5e; --imp-soft:#2a2213; --ops:#9aa0b3; --ops-soft:#21242d;\n      --crit:#f0879a; --focus:#8b93ee;\n    }\n  }\n  :root[data-theme=\"light\"]{\n    --bg:#f7f8fb; --panel:#ffffff; --ink:#171a21; --ink-2:#5a6072; --ink-3:#8a90a2;\n    --line:#e7e9f0; --line-2:#eef0f6; --accent:#4b53c4; --accent-soft:#eceef9;\n    --bug:#d6455f; --bug-soft:#fbe9ec; --feat:#0f8f7e; --feat-soft:#e2f3ef;\n    --imp:#c07a15; --imp-soft:#f8efdd; --ops:#7b8194; --ops-soft:#eef0f4; --crit:#c0392b; --focus:#4b53c4;\n  }\n  :root[data-theme=\"dark\"]{\n    --bg:#0f1116; --panel:#171a22; --ink:#e9ebf2; --ink-2:#a2a8bb; --ink-3:#71778a;\n    --line:#262a36; --line-2:#20242e; --accent:#8b93ee; --accent-soft:#20233a;\n    --bug:#f0879a; --bug-soft:#2c1a20; --feat:#5fcdb6; --feat-soft:#152621;\n    --imp:#e0ad5e; --imp-soft:#2a2213; --ops:#9aa0b3; --ops-soft:#21242d; --crit:#f0879a; --focus:#8b93ee;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--jp);line-height:1.65;\n    -webkit-font-smoothing:antialiased;font-feature-settings:\"palt\" 1}\n  .wrap{max-width:1120px;margin:0 auto;padding:40px 22px 80px}\n  .tnum{font-variant-numeric:tabular-nums}\n\n  header.masthead{border-bottom:2px solid var(--ink);padding-bottom:18px;margin-bottom:26px}\n  .eyebrow{font-size:12px;letter-spacing:.22em;color:var(--accent);font-weight:700;margin:0 0 8px}\n  h1{font-size:clamp(26px,4vw,38px);margin:0 0 6px;letter-spacing:.01em;font-weight:800;text-wrap:balance}\n  .sub{color:var(--ink-2);font-size:15px;margin:0}\n  .meta{display:flex;flex-wrap:wrap;gap:8px 22px;margin-top:16px;font-size:12.5px;color:var(--ink-2)}\n  .meta b{color:var(--ink);font-weight:700}\n\n  .stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:24px 0 28px}\n  .stat{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:15px 16px;position:relative;overflow:hidden}\n  .stat .k{font-size:12px;color:var(--ink-2);font-weight:600;letter-spacing:.02em}\n  .stat .v{font-size:30px;font-weight:800;margin-top:2px;line-height:1}\n  .stat .u{font-size:12px;color:var(--ink-3);margin-left:3px;font-weight:600}\n  .stat::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--sc,var(--accent))}\n\n  .toolbar{display:flex;flex-wrap:wrap;gap:10px 14px;align-items:center;margin-bottom:16px}\n  .chips{display:flex;flex-wrap:wrap;gap:7px}\n  .chip{font:inherit;font-size:12.5px;font-weight:600;padding:6px 13px;border-radius:999px;border:1px solid var(--line);\n    background:var(--panel);color:var(--ink-2);cursor:pointer;transition:.14s;display:inline-flex;align-items:center;gap:6px}\n  .chip:hover{border-color:var(--accent);color:var(--ink)}\n  .chip[aria-pressed=\"true\"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}\n  .chip .dot{width:8px;height:8px;border-radius:50%}\n  .chip.k-bug .dot{background:var(--bug)} .chip.k-feat .dot{background:var(--feat)}\n  .chip.k-imp .dot{background:var(--imp)} .chip.k-ops .dot{background:var(--ops)}\n  .search{margin-left:auto;flex:1;min-width:190px;max-width:320px}\n  .search input{width:100%;font:inherit;font-size:13.5px;padding:8px 13px;border-radius:9px;border:1px solid var(--line);\n    background:var(--panel);color:var(--ink)}\n  .search input::placeholder{color:var(--ink-3)}\n  :focus-visible{outline:2px solid var(--focus);outline-offset:2px}\n\n  .count-line{font-size:12.5px;color:var(--ink-2);margin:0 2px 10px}\n\n  .ledger{display:flex;flex-direction:column;gap:9px}\n  .row{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px 16px 14px 18px;\n    position:relative;overflow:hidden}\n  .row::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--rc)}\n  .row.k-bug{--rc:var(--bug)} .row.k-feat{--rc:var(--feat)} .row.k-imp{--rc:var(--imp)} .row.k-ops{--rc:var(--ops)}\n  .row-top{display:flex;flex-wrap:wrap;align-items:center;gap:8px 10px;margin-bottom:7px}\n  .tag{font-size:11px;font-weight:700;padding:3px 9px;border-radius:6px;letter-spacing:.02em;white-space:nowrap}\n  .tag.k-bug{background:var(--bug-soft);color:var(--bug)} .tag.k-feat{background:var(--feat-soft);color:var(--feat)}\n  .tag.k-imp{background:var(--imp-soft);color:var(--imp)} .tag.k-ops{background:var(--ops-soft);color:var(--ops)}\n  .area{font-size:12px;color:var(--ink-2);font-weight:600;background:var(--line-2);padding:3px 9px;border-radius:6px}\n  .crit{font-size:11px;font-weight:800;color:#fff;background:var(--crit);padding:3px 8px;border-radius:6px;letter-spacing:.03em}\n  .date{margin-left:auto;font-size:12px;color:var(--ink-3);font-family:var(--mono)}\n  .cid{font-size:11.5px;color:var(--ink-3);font-family:var(--mono);background:var(--line-2);padding:2px 7px;border-radius:5px}\n  .title{font-size:15px;font-weight:700;margin:0 0 6px;letter-spacing:.01em}\n  .cf{display:grid;grid-template-columns:auto 1fr;gap:3px 12px;font-size:13px;color:var(--ink-2)}\n  .cf .lb{font-weight:700;color:var(--ink-3);font-size:11.5px;letter-spacing:.04em;padding-top:1px}\n  .cf .tx{color:var(--ink-2)}\n  .cf .tx b{color:var(--ink);font-weight:700}\n  .empty{text-align:center;color:var(--ink-3);padding:44px;font-size:14px}\n\n  section.block{margin-top:44px}\n  .block h2{font-size:18px;font-weight:800;margin:0 0 4px;display:flex;align-items:center;gap:9px}\n  .block h2::before{content:\"\";width:10px;height:20px;border-radius:3px;background:var(--accent)}\n  .block .lead{color:var(--ink-2);font-size:13.5px;margin:0 0 16px}\n  .todo{display:flex;flex-direction:column;gap:8px}\n  .titem{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:13px 15px;display:flex;gap:13px;align-items:flex-start}\n  .titem .st{font-size:11px;font-weight:800;padding:4px 9px;border-radius:6px;white-space:nowrap;margin-top:1px}\n  .st.plan{background:var(--accent-soft);color:var(--accent)}\n  .st.hold{background:var(--imp-soft);color:var(--imp)}\n  .st.done{background:var(--feat-soft);color:var(--feat)}\n  .titem .body b{display:block;font-size:14px;color:var(--ink);margin-bottom:2px;font-weight:700}\n  .titem .body span{font-size:12.5px;color:var(--ink-2)}\n  .titem .prio{margin-left:auto;font-size:11px;font-weight:700;color:var(--ink-3);white-space:nowrap}\n\n  .docs{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}\n  .doc{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:15px 16px}\n  .doc .h{font-weight:700;font-size:14px;margin:0 0 8px;display:flex;align-items:center;gap:8px}\n  .doc .h .n{font-family:var(--mono);font-size:12px;color:#fff;background:var(--accent);border-radius:5px;padding:1px 7px}\n  .doc ul{margin:0;padding-left:18px;font-size:12.8px;color:var(--ink-2)}\n  .doc ul li{margin:4px 0}\n  .doc .note{font-size:11.5px;color:var(--ink-3);margin-top:9px;padding-top:9px;border-top:1px dashed var(--line)}\n\n  footer{margin-top:48px;padding-top:18px;border-top:1px solid var(--line);font-size:12px;color:var(--ink-3)}\n  @media (max-width:560px){\n    .cf{grid-template-columns:1fr;gap:2px} .cf .lb{margin-top:6px}\n    .date{width:100%;margin-left:0;order:5}\n  }\n</style>\n</head>\n<body>\n\n<div class=\"wrap\">\n  <header class=\"masthead\"><p class=\"eyebrow\">変更管理台帳 ／ CHANGE LOG</p><h1>つむぎ 修正・機能追加の記録</h1>\n    <p class=\"sub\">いつ・どこを・なぜ直したかを記録し、不具合対応の証跡として残す一覧です。</p>\n    <div class=\"meta\"><span>対象システム <b>つむぎ（通所介護 管理アプリ）</b></span><span>記録期間 <b class=\"tnum\">2026-07-16 〜 07-26</b></span><span>総件数 <b class=\"tnum\" id=\"m-total\">95</b> 件</span><span>版 <b>rev. 7c18dfb</b></span></div>\n  </header>\n  <div class=\"stats\">\n    <div class=\"stat\" style=\"--sc:var(--bug)\"><div class=\"k\">バグ修正</div><div class=\"v tnum\" id=\"s-bug\">33</div></div>\n    <div class=\"stat\" style=\"--sc:var(--feat)\"><div class=\"k\">機能追加</div><div class=\"v tnum\" id=\"s-feat\">33</div></div>\n    <div class=\"stat\" style=\"--sc:var(--imp)\"><div class=\"k\">改善・調整</div><div class=\"v tnum\" id=\"s-imp\">29</div></div>\n    <div class=\"stat\" style=\"--sc:var(--crit)\"><div class=\"k\">重大な不具合</div><div class=\"v tnum\" id=\"s-crit\">12</div><span class=\"u\">データ保全</span></div>\n  </div>\n  <div class=\"toolbar\"><div class=\"chips\" id=\"kind-chips\"><button class=\"chip\" data-kind=\"all\" aria-pressed=\"true\">すべて</button><button class=\"chip k-bug\" data-kind=\"bug\" aria-pressed=\"false\"><span class=\"dot\"></span>バグ修正</button><button class=\"chip k-feat\" data-kind=\"feat\" aria-pressed=\"false\"><span class=\"dot\"></span>機能追加</button><button class=\"chip k-imp\" data-kind=\"imp\" aria-pressed=\"false\"><span class=\"dot\"></span>改善</button></div>\n    <div class=\"search\"><input id=\"q\" type=\"search\" placeholder=\"キーワードで絞り込み（例: 連絡帳 / 同期 / 計画書）\" aria-label=\"キーワード検索\"></div></div>\n  <div class=\"chips\" id=\"area-chips\" style=\"margin-bottom:16px\"><button class=\"chip\" data-area=\"all\" aria-pressed=\"true\">全領域</button><button class=\"chip\" data-area=\"同期\" aria-pressed=\"false\">同期 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">11</span></button><button class=\"chip\" data-area=\"提供記録\" aria-pressed=\"false\">提供記録 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">10</span></button><button class=\"chip\" data-area=\"分析/提供記録\" aria-pressed=\"false\">分析/提供記録 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">2</span></button><button class=\"chip\" data-area=\"連絡\" aria-pressed=\"false\">連絡 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">1</span></button><button class=\"chip\" data-area=\"LIFE加算\" aria-pressed=\"false\">LIFE加算 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">8</span></button><button class=\"chip\" data-area=\"分析\" aria-pressed=\"false\">分析 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">9</span></button><button class=\"chip\" data-area=\"分析個人/LIFE加算\" aria-pressed=\"false\">分析個人/LIFE加算 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">1</span></button><button class=\"chip\" data-area=\"スケジュール/提供記録\" aria-pressed=\"false\">スケジュール/提供記録 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">1</span></button><button class=\"chip\" data-area=\"利用者マスタ\" aria-pressed=\"false\">利用者マスタ <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">21</span></button><button class=\"chip\" data-area=\"ケアマネ連携\" aria-pressed=\"false\">ケアマネ連携 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">5</span></button><button class=\"chip\" data-area=\"ホーム\" aria-pressed=\"false\">ホーム <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">2</span></button><button class=\"chip\" data-area=\"家族アプリ\" aria-pressed=\"false\">家族アプリ <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">4</span></button><button class=\"chip\" data-area=\"各種設定\" aria-pressed=\"false\">各種設定 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">5</span></button><button class=\"chip\" data-area=\"計画書\" aria-pressed=\"false\">計画書 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">10</span></button><button class=\"chip\" data-area=\"連絡帳\" aria-pressed=\"false\">連絡帳 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">3</span></button><button class=\"chip\" data-area=\"体力測定\" aria-pressed=\"false\">体力測定 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">1</span></button><button class=\"chip\" data-area=\"管理局\" aria-pressed=\"false\">管理局 <span class=\"tnum\" style=\"color:var(--ink-3);font-size:11px\">1</span></button></div>\n  <p class=\"count-line\" id=\"count-line\">表示 95 件 ／ 全 95 件</p>\n  <div class=\"ledger\" id=\"ledger\">\n    <article class=\"row k-bug\" data-kind=\"bug\" data-area=\"同期\" data-text=\"保険証・負担割合証・フェイスシート等が他店の更新で反映されない/巻き戻る不具合を修正介護保険証/負担割合証のメタ・フェイスシート・担当者会議・アセスメント等が入るpersonalfile(入れ子)と、負担割合の有効期間(costburdenfrom/to)・被保険者番号が、同期の項目単位保護(_fieldts)の対象外だった。そのため別の項目を触った“少し古いデータの端末”が保存すると、他店で更新した保険証・フェイスシートが「新しいスナップショット」の名目でまるごと巻き戻っていた(保険証以外も同じ弱点)。同期の項目単位保護を拡張。①保護対象に costburdenfrom/costburdento/被保険者番号 を追加。②personalfile をサブキー単位の時刻(pf:キー)でマージ(各書類・フェイスシート・会議記録ごとに新しい方を採用。アセスメントは従来の和集合を維持)。③介護度・負担割合の変更履歴を和集合で保持し、両端末の追記=過去記録を失わないように。既存クラウドは項目時刻を持たないため当面は従来挙動にフォールバックし、以降の保存で段階的に保護が付く(後方互換)。同期7c18dfb\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-26</span></div>\n      <p class=\"title\">保険証・負担割合証・フェイスシート等が他店の更新で反映されない/巻き戻る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">介護保険証/負担割合証のメタ・フェイスシート・担当者会議・アセスメント等が入るpersonalFile(入れ子)と、負担割合の有効期間(costBurdenFrom/To)・被保険者番号が、同期の項目単位保護(_fieldTs)の対象外だった。そのため別の項目を触った“少し古いデータの端末”が保存すると、他店で更新した保険証・フェイスシートが「新しいスナップショット」の名目でまるごと巻き戻っていた(保険証以外も同じ弱点)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同期の項目単位保護を拡張。①保護対象に costBurdenFrom/costBurdenTo/被保険者番号 を追加。②personalFile をサブキー単位の時刻(pf:キー)でマージ(各書類・フェイスシート・会議記録ごとに新しい方を採用。アセスメントは従来の和集合を維持)。③介護度・負担割合の変更履歴を和集合で保持し、両端末の追記=過去記録を失わないように。既存クラウドは項目時刻を持たないため当面は従来挙動にフォールバックし、以降の保存で段階的に保護が付く(後方互換)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7c18dfb</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"提供記録\" data-text=\"テンキー日本語ラベルを大きく表示＋言い回しを変更（bs→1字消す／tab→次へ）日本語化したテンキーのラベルが小さく見づらかった。bs・tabは別の言い回しの方が直感的との要望。bs=1字消す(2行)／tab=次へ に変更。日本語ラベルのフォントを拡大（全削除=0.66倍、1字消す/次へ/確定=0.82倍）。キー値は英語のままで動作は不変。提供記録f4da324\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-26</span></div>\n      <p class=\"title\">テンキー日本語ラベルを大きく表示＋言い回しを変更（BS→1字消す／TAB→次へ）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日本語化したテンキーのラベルが小さく見づらかった。BS・TABは別の言い回しの方が直感的との要望。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>BS=1字消す(2行)／TAB=次へ に変更。日本語ラベルのフォントを拡大（全削除=0.66倍、1字消す/次へ/確定=0.82倍）。キー値は英語のままで動作は不変。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f4da324</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"提供記録\" data-text=\"テンキーの特殊キーを日本語表示に（del→全削除／bs→1文字削除／tab→右へ／enter→確定）テンキーのdel/bs/tab/enterが英語表記で、意味が分からない職員がいた。表示ラベルを日本語化（del=全削除／bs=1文字削除〔2行〕／tab=右へ／enter=確定）。キー値は英語のままロジックで使用するため動作は不変。日本語ラベルはボタン内に収まるようフォントサイズを調整。提供記録cf98527\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-26</span></div>\n      <p class=\"title\">テンキーの特殊キーを日本語表示に（DEL→全削除／BS→1文字削除／TAB→右へ／ENTER→確定）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">テンキーのDEL/BS/TAB/ENTERが英語表記で、意味が分からない職員がいた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>表示ラベルを日本語化（DEL=全削除／BS=1文字削除〔2行〕／TAB=右へ／ENTER=確定）。キー値は英語のままロジックで使用するため動作は不変。日本語ラベルはボタン内に収まるようフォントサイズを調整。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cf98527</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"分析/提供記録\" data-text=\"気分列幅を状態列と同じに＋日々の詳細記録の気分理由ツールチップをipad対応にサービス提供記録の気分列が状態列より広かった。日々の詳細記録の気分絵文字はnative title頼りで、ipad等タッチ端末ではカーソルを合わせても理由が表示されなかった。サービス提供記録の気分列ヘッダ幅を60→34(状態列と同じ)にしセルのminwidthも撤去。日々の詳細記録の気分絵文字に、ホバー(onpointerenter)とタップ(onclick)の両方で理由を表示する浮動ツールチップを実装(タップ時は2.6秒で自動クローズ、理由なしは「（理由なし）」)。分析/提供記録c18172e\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析/提供記録</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">気分列幅を状態列と同じに＋日々の詳細記録の気分理由ツールチップをiPad対応に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">サービス提供記録の気分列が状態列より広かった。日々の詳細記録の気分絵文字はnative title頼りで、iPad等タッチ端末ではカーソルを合わせても理由が表示されなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サービス提供記録の気分列ヘッダ幅を60→34(状態列と同じ)にしセルのminWidthも撤去。日々の詳細記録の気分絵文字に、ホバー(onPointerEnter)とタップ(onClick)の両方で理由を表示する浮動ツールチップを実装(タップ時は2.6秒で自動クローズ、理由なしは「（理由なし）」)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c18172e</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"分析/提供記録\" data-text=\"気分表示を絵文字のみに整理＋日々の詳細記録の見やすさ改善サービス提供記録の気分に💬コメント絵文字が付いて列幅を取っていた。分析個人『日々の詳細記録』は気分の理由テキストが括弧書きで表示され横に広がっていた。特記列が狭く、行のストライプが薄くて見分けにくかった。サービス提供記録(検索一覧)の気分から💬を削除し気分列幅を縮小(minwidth 52→36)、理由はホバー(title)で従来通り。日々の詳細記録の気分(通)/(帰)は絵文字のみ表示にし理由テキストを廃止、絵文字ホバーで気分理由を表示。特記列の幅を拡大(minwidth 220→340)。奇数行のストライプ背景グレーを濃く(#fafbfc→#eef2f6)。分析/提供記録d7a9976\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">分析/提供記録</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">気分表示を絵文字のみに整理＋日々の詳細記録の見やすさ改善</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">サービス提供記録の気分に💬コメント絵文字が付いて列幅を取っていた。分析個人『日々の詳細記録』は気分の理由テキストが括弧書きで表示され横に広がっていた。特記列が狭く、行のストライプが薄くて見分けにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>サービス提供記録(検索一覧)の気分から💬を削除し気分列幅を縮小(minWidth 52→36)、理由はホバー(title)で従来通り。日々の詳細記録の気分(通)/(帰)は絵文字のみ表示にし理由テキストを廃止、絵文字ホバーで気分理由を表示。特記列の幅を拡大(minWidth 220→340)。奇数行のストライプ背景グレーを濃く(#fafbfc→#eef2f6)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d7a9976</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"連絡\" data-text=\"休み連絡・各種連絡の送付先fax番号を表示(マスタ補完)＋ワンクリックコピー送付状の送付先faxが利用者のcmfaxのみ参照で、利用者にfax未設定だと表示されなかった(各種設定のケアマネ事業所情報にはfaxがある)。各種設定のケアマネ事業所情報(cmoffices)から事業所名一致でfax番号を補完して表示。fax番号の右にコピーボタン(copyfaxbutton)を新設し、複合機にそのまま貼り付けられるようクリップボードへコピー(navigator.clipboard、非対応時はexeccommandでフォールバック)。コピーボタンはno-printクラスで印刷/pdf時は非表示。連絡684adcb\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">連絡</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">休み連絡・各種連絡の送付先FAX番号を表示(マスタ補完)＋ワンクリックコピー</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">送付状の送付先FAXが利用者のcmFaxのみ参照で、利用者にFAX未設定だと表示されなかった(各種設定のケアマネ事業所情報にはFAXがある)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各種設定のケアマネ事業所情報(cmOffices)から事業所名一致でFAX番号を補完して表示。FAX番号の右にコピーボタン(CopyFaxButton)を新設し、複合機にそのまま貼り付けられるようクリップボードへコピー(navigator.clipboard、非対応時はexecCommandでフォールバック)。コピーボタンはno-printクラスで印刷/PDF時は非表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">684adcb</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"LIFE加算\" data-text=\"科学的介護推進・adl維持等の帳票(印刷/pdf)を追加lifeの科学的介護推進(tifi2024)・adl維持等(aint2024)は評価内容を紙様式で出す帳票が無く、csvのみだった。lifehubviewに印刷機能(onshowprintpreview)を渡し、両様式カードに「帳票印刷」ボタンを追加。科学的介護推進に関する評価=事業所/利用者/評価日/介護度/自立度・barthel一覧・身長体重・口腔(義歯/むせ/歯の汚れ/歯肉)・認知症診断・生活認知機能尺度7設問(点数+選択肢)・vitalityをa4紙様式で出力。adl維持等=ヘッダ+対象月区分+barthel一覧。元データ=選択中利用者の最新adl評価+固有項目。生活機能チェック(3-2)/個別機能訓練(3-3)の帳票は各計画書画面の印刷/pdfから。life加算a7119db\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">科学的介護推進・ADL維持等の帳票(印刷/PDF)を追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEの科学的介護推進(TIFI2024)・ADL維持等(AINT2024)は評価内容を紙様式で出す帳票が無く、CSVのみだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LifeHubViewに印刷機能(onShowPrintPreview)を渡し、両様式カードに「帳票印刷」ボタンを追加。科学的介護推進に関する評価=事業所/利用者/評価日/介護度/自立度・Barthel一覧・身長体重・口腔(義歯/むせ/歯の汚れ/歯肉)・認知症診断・生活認知機能尺度7設問(点数+選択肢)・VitalityをA4紙様式で出力。ADL維持等=ヘッダ+対象月区分+Barthel一覧。元データ=選択中利用者の最新ADL評価+固有項目。生活機能チェック(3-2)/個別機能訓練(3-3)の帳票は各計画書画面の印刷/PDFから。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a7119db</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"LIFE加算\" data-text=\"個別機能訓練 idua2024(103列)のlife提出csvを実装(v1)＋計画書にコード入力uilifeの4様式のうち個別機能訓練(idua2024・最大の103列)が未対応だった。目標や訓練内容はコード(icf/プログラム/職種/合併症/傷病名)での提出が必要。life_idua2024_columns(103)/buildidua2024row/validateidua2024を実装しlife_formsにsource=kinouで登録(addon=個別機能訓練加算ii)。元データ=個別機能訓練計画書(3-3)。マスタ同梱=icf目標55(§9.2)/訓練プログラム18(§9.3)/合併症23分類/職種名(准看護師=050のみ確定・他要確認)。本人家族希望・社会参加・居宅環境・治療経過・目標文→内容列、発症/入退院日→年月日分割、訓練内容→プログラムコード自動推定、達成度文→コード、自立度/介護度/管理番号/versionを自動生成。3-3計画書に「life提出用コード」入力(傷病名/合併症/目標icf/プログラム/職種/達成度=editing.life)を新設。提出ダッシュボード・単票出力もkinou元データに対応。傷病名27388件は任意入力扱い。life加算34f64f8 / a69388f\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">個別機能訓練 IDUA2024(103列)のLIFE提出CSVを実装(v1)＋計画書にコード入力UI</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEの4様式のうち個別機能訓練(IDUA2024・最大の103列)が未対応だった。目標や訓練内容はコード(ICF/プログラム/職種/合併症/傷病名)での提出が必要。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE_IDUA2024_COLUMNS(103)/buildIdua2024Row/validateIdua2024を実装しLIFE_FORMSにsource=kinouで登録(addon=個別機能訓練加算II)。元データ=個別機能訓練計画書(3-3)。マスタ同梱=ICF目標55(§9.2)/訓練プログラム18(§9.3)/合併症23分類/職種名(准看護師=050のみ確定・他要確認)。本人家族希望・社会参加・居宅環境・治療経過・目標文→内容列、発症/入退院日→年月日分割、訓練内容→プログラムコード自動推定、達成度文→コード、自立度/介護度/管理番号/versionを自動生成。3-3計画書に「LIFE提出用コード」入力(傷病名/合併症/目標ICF/プログラム/職種/達成度=editing.life)を新設。提出ダッシュボード・単票出力もkinou元データに対応。傷病名27388件は任意入力扱い。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">34f64f8 / a69388f</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"分析\" data-text=\"月別稼働率グラフで7月時点に8月の稼働率が出てしまう不具合を修正月別グラフは年度12ヶ月を常に表示。当月は今日までにcapする処理はあったが、未来月を除外する処理が無く、稼働率の照合が「記録に年がある時だけ年フィルタ」だったため、年情報のない同月番号の記録(前年8月分等)を未来月が拾い、売上¥0なのに稼働率91%等と表示されていた。_isfuturemonth(当月より後)を判定し、未来月は稼働率rate=null(グラフ・表で非表示)に。年なし記録の混入を防ぎ、稼働率の線は当月までで止まる。売上の年付き照合は元々正しいため¥0表示は不変。分析9011a1f\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-24</span></div>\n      <p class=\"title\">月別稼働率グラフで7月時点に8月の稼働率が出てしまう不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">月別グラフは年度12ヶ月を常に表示。当月は今日までにcapする処理はあったが、未来月を除外する処理が無く、稼働率の照合が「記録に年がある時だけ年フィルタ」だったため、年情報のない同月番号の記録(前年8月分等)を未来月が拾い、売上¥0なのに稼働率91%等と表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>_isFutureMonth(当月より後)を判定し、未来月は稼働率rate=null(グラフ・表で非表示)に。年なし記録の混入を防ぎ、稼働率の線は当月までで止まる。売上の年付き照合は元々正しいため¥0表示は不変。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9011a1f</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"LIFE加算\" data-text=\"生活機能チェック(func2024・52列)のlife提出csvを追加＋様式横断にsource導入lifeはtifi2024/aint2024のみで生活機能チェック(様式3-2)のfunc2024が未対応。ダッシュボード/出力もbarthel(adlrecords)固定で別データ元の様式を扱えなかった。life_func2024_columns(52列)/buildfunc2024row/validatefunc2024を新設しlife_formsにfunc2024を登録(addon=個別機能訓練加算ⅱ)。元データ=生活機能チェック(seikatsukinourecords)。adl10項目はseikatsuadltobarthel→lifebicode(§6.4 bi段階コード)、iadl3/起居動作5は自立=3/見守り=2/一部介助=1/全介助=0。課題の有無は自動判定(自立=無/他=有)。作成日の和暦→yyyymmdd変換(reiwatoymd)追加。life_formsにsource(adl/seikatsu)を追加し提出ダッシュボード・単票を元データで分岐(tifi/aintは従来通り)。func2024はマスタ不要。life加算692f5a2\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">生活機能チェック(FUNC2024・52列)のLIFE提出CSVを追加＋様式横断にsource導入</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEはTIFI2024/AINT2024のみで生活機能チェック(様式3-2)のFUNC2024が未対応。ダッシュボード/出力もBarthel(adlRecords)固定で別データ元の様式を扱えなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE_FUNC2024_COLUMNS(52列)/buildFunc2024Row/validateFunc2024を新設しLIFE_FORMSにFUNC2024を登録(addon=個別機能訓練加算Ⅱ)。元データ=生活機能チェック(seikatsuKinouRecords)。ADL10項目はseikatsuAdlToBarthel→lifeBiCode(§6.4 BI段階コード)、IADL3/起居動作5は自立=3/見守り=2/一部介助=1/全介助=0。課題の有無は自動判定(自立=無/他=有)。作成日の和暦→YYYYMMDD変換(reiwaToYmd)追加。LIFE_FORMSにsource(adl/seikatsu)を追加し提出ダッシュボード・単票を元データで分岐(TIFI/AINTは従来通り)。FUNC2024はマスタ不要。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">692f5a2</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"LIFE加算\" data-text=\"adl維持等加算(aint2024)のcsv出力を追加・ダッシュボード/出力を様式横断化lifeは科学的介護推進(tifi2024)のみ対応で、adl維持等加算のcsvが無かった。aint2024全23列(既存barthel評価を流用・first_month/sixth_monthフラグ対応)を実装。adl評価編集に対象月区分(初月/6か月後/どちらでもない)を追加し利用開始日から目安月を表示。提出ダッシュボード・単票/まとめcsv出力を様式横断(life_forms)に一般化し、加算が複数onなら様式プルダウンでtifi2024/aint2024を切替。life加算4c8ef63\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">ADL維持等加算(AINT2024)のCSV出力を追加・ダッシュボード/出力を様式横断化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFEは科学的介護推進(TIFI2024)のみ対応で、ADL維持等加算のCSVが無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>AINT2024全23列(既存Barthel評価を流用・first_month/sixth_monthフラグ対応)を実装。ADL評価編集に対象月区分(初月/6か月後/どちらでもない)を追加し利用開始日から目安月を表示。提出ダッシュボード・単票/まとめCSV出力を様式横断(LIFE_FORMS)に一般化し、加算が複数ONなら様式プルダウンでTIFI2024/AINT2024を切替。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">4c8ef63</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"LIFE加算\" data-text=\"科学的介護推進: 提出ダッシュボード＋複数利用者まとめcsv出力csv出力が利用者1名ずつだった。提出月に複数利用者をまとめて出力できず、誰が提出可/未評価/エラーかの一覧も無かった。life・加算画面に提出ダッシュボード(利用者×状態=提出可/エラー/未評価・確認事項)を追加。行クリックでその利用者に切替。『まとめてcsv出力』で提出可の全利用者を1つのtifi2024_yyyymm.csvに出力(未評価・エラーは自動除外し確認一覧に表示)。各行の管理番号は利用者ごとの評価年月で採番。提出年月セレクタでファイル名整理。life加算74b1da2\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">科学的介護推進: 提出ダッシュボード＋複数利用者まとめCSV出力</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">CSV出力が利用者1名ずつだった。提出月に複数利用者をまとめて出力できず、誰が提出可/未評価/エラーかの一覧も無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE・加算画面に提出ダッシュボード(利用者×状態=提出可/エラー/未評価・確認事項)を追加。行クリックでその利用者に切替。『まとめてCSV出力』で提出可の全利用者を1つのTIFI2024_YYYYMM.csvに出力(未評価・エラーは自動除外し確認一覧に表示)。各行の管理番号は利用者ごとの評価年月で採番。提出年月セレクタでファイル名整理。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">74b1da2</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"分析個人/LIFE加算\" data-text=\"気分表示を絵文字＋ホバーにコンパクト化／life事業所情報は各種設定に一元化①分析個人『日々の詳細記録』で気分の理由テキストが長いと行が縦に伸びて見づらかった。②lifeの事業所番号・保険者番号がlife画面専用カードにあり、事業所情報と二重管理気味だった。①気分列を絵文字だけの一定行高さ表示に変更し、理由はホバー(title)で表示(理由ありは💬)。②事業所番号・保険者番号(既定)・サービス種類コード・csvバージョンを『各種設定→事業所情報』に入力項目として設置し、life・加算のcsvはそこから読込(専用カードは表示のみに)。分析個人/life加算55305ca\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">分析個人/LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">気分表示を絵文字＋ホバーにコンパクト化／LIFE事業所情報は各種設定に一元化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①分析個人『日々の詳細記録』で気分の理由テキストが長いと行が縦に伸びて見づらかった。②LIFEの事業所番号・保険者番号がLIFE画面専用カードにあり、事業所情報と二重管理気味だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①気分列を絵文字だけの一定行高さ表示に変更し、理由はホバー(title)で表示(理由ありは💬)。②事業所番号・保険者番号(既定)・サービス種類コード・CSVバージョンを『各種設定→事業所情報』に入力項目として設置し、LIFE・加算のCSVはそこから読込(専用カードは表示のみに)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">55305ca</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"LIFE加算\" data-text=\"life設定(事業所/保険者番号/サービスコード/version)＋利用者ごと保険者番号＋生活認知機能尺度の正式文言科学的介護推進csvで事業所番号・保険者番号が空欄(&#x27;要確認&#x27;警告)だった。また生活・認知機能尺度の7設問が仮ラベルのままだった。life・加算画面に『life設定』(事業所番号・保険者番号既定・サービス種類コード・施設通所区分・csvバージョン=systemsettings.life)を追加。利用者基本情報に被保険者番号表示＋利用者ごとの保険者番号入力を追加(csvは利用者→無ければ事業所既定)。生活・認知機能尺度7設問を別紙様式3の正式文言に差し替え、各点数の選択肢説明も表示。life加算424891d\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">LIFE設定(事業所/保険者番号/サービスコード/version)＋利用者ごと保険者番号＋生活認知機能尺度の正式文言</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">科学的介護推進CSVで事業所番号・保険者番号が空欄(&#x27;要確認&#x27;警告)だった。また生活・認知機能尺度の7設問が仮ラベルのままだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE・加算画面に『LIFE設定』(事業所番号・保険者番号既定・サービス種類コード・施設通所区分・CSVバージョン=systemSettings.life)を追加。利用者基本情報に被保険者番号表示＋利用者ごとの保険者番号入力を追加(CSVは利用者→無ければ事業所既定)。生活・認知機能尺度7設問を別紙様式3の正式文言に差し替え、各点数の選択肢説明も表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">424891d</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"スケジュール/提供記録\" data-text=\"担当者会議のスケジュール→記録入力ショートカット／提供記録の全画面に連絡帳ボタン①本日のスケジュールで担当者会議(利用者紐付き)を設定していても、記録入力までの導線が無かった。②サービス提供記録入力を全画面にすると連絡帳ボタンが消えていた。①本日のスケジュールの担当者会議イベントの詳細に『担当者会議記録を入力』ボタンを追加し、押すとその利用者の個人ファイル(ケアマネジメント)で会議記録の新規入力を即開くように。②全画面ヘッダにも『連絡帳』ボタンを追加。スケジュール/提供記録9c435e7\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">スケジュール/提供記録</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">担当者会議のスケジュール→記録入力ショートカット／提供記録の全画面に連絡帳ボタン</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①本日のスケジュールで担当者会議(利用者紐付き)を設定していても、記録入力までの導線が無かった。②サービス提供記録入力を全画面にすると連絡帳ボタンが消えていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①本日のスケジュールの担当者会議イベントの詳細に『担当者会議記録を入力』ボタンを追加し、押すとその利用者の個人ファイル(ケアマネジメント)で会議記録の新規入力を即開くように。②全画面ヘッダにも『連絡帳』ボタンを追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9c435e7</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"LIFE加算\" data-text=\"科学的介護推進体制加算(tifi2024)のlife提出用csv出力を実装(第1弾)life(科学的介護情報システム)へ提出する加算データを一元入力→取込用csvを生成する仕組みが未実装だった(まるっとlifeはexcel運用)。まず科学的介護推進体制加算から着手。life・加算画面に、科学的介護推進の固有入力(身長体重/口腔/認知症診断/生活認知機能尺度7設問/vitality)を追加し、既存のadl評価(barthel)・フェイスシートの自立度を流用して全114列のcsv(tifi2024)を出力。§6.4コード変換(bi段階・自立度・要介護度)、管理番号採番、utf-8/cr-lf、提出前チェック(必須/未来日付/整合)を実装。提出頻度は令和6年度改定に合わせ3ヶ月に修正。次段: 事業所/保険者番号のlife設定・複数まとめ出力・帳票印刷・adl維持等/個別機能訓練の様式。life加算17f432e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">科学的介護推進体制加算(TIFI2024)のLIFE提出用CSV出力を実装(第1弾)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">LIFE(科学的介護情報システム)へ提出する加算データを一元入力→取込用CSVを生成する仕組みが未実装だった(まるっとLIFEはExcel運用)。まず科学的介護推進体制加算から着手。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>LIFE・加算画面に、科学的介護推進の固有入力(身長体重/口腔/認知症診断/生活認知機能尺度7設問/Vitality)を追加し、既存のADL評価(Barthel)・フェイスシートの自立度を流用して全114列のCSV(TIFI2024)を出力。§6.4コード変換(BI段階・自立度・要介護度)、管理番号採番、UTF-8/CR-LF、提出前チェック(必須/未来日付/整合)を実装。提出頻度は令和6年度改定に合わせ3ヶ月に修正。次段: 事業所/保険者番号のLIFE設定・複数まとめ出力・帳票印刷・ADL維持等/個別機能訓練の様式。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">17f432e</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"利用者マスタ\" data-text=\"運動メニュー規定値をハイフン(ー)/クリアにすると過去の記録まで遡って変わる不具合を修正テンキーの ○/×/ー ボタンは押下で即確定(自動クローズ)するため、数値変更のように『別セルへ移動→保存で&quot;いつから反映&quot;を確認』の流れに乗らず、自動保存で当日付のまま(場合により履歴無しで)確定され、提供記録入力で過去日を遡ると規定値が全てハイフンになっていた。運動メニュー・個別運動の規定値変更は、数値・ハイフン・クリアを問わず必ず『いつから反映しますか』モーダルを表示。自動保存でも当日付で勝手に確定せず、適用開始日を選んで日付単位で履歴管理(過去は旧値のまま保持)。全期間へ適用したい場合はモーダルの『分けない』を選択。利用者マスタ8d48609\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">運動メニュー規定値をハイフン(ー)/クリアにすると過去の記録まで遡って変わる不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">テンキーの ○/×/ー ボタンは押下で即確定(自動クローズ)するため、数値変更のように『別セルへ移動→保存で&quot;いつから反映&quot;を確認』の流れに乗らず、自動保存で当日付のまま(場合により履歴無しで)確定され、提供記録入力で過去日を遡ると規定値が全てハイフンになっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>運動メニュー・個別運動の規定値変更は、数値・ハイフン・クリアを問わず必ず『いつから反映しますか』モーダルを表示。自動保存でも当日付で勝手に確定せず、適用開始日を選んで日付単位で履歴管理(過去は旧値のまま保持)。全期間へ適用したい場合はモーダルの『分けない』を選択。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8d48609</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"ケアマネ連携\" data-text=\"フェイスシート編集の更新通知にも項目名(本人情報・留意点・被保険者番号等)を表示フェイスシートに追加した項目(氏名・住所・電話・被保険者番号・留意点・その他関係者)が差分表(fs_field_labels)に無く、フェイスシートで編集しても『フェイスシートの編集』に項目名が出なかった。fs_field_labels にこれらを追加し、フェイスシート経由の編集でも『フェイスシートの編集（○○）』と項目名が出るように(既往歴は登録済み)。ケアマネ連携fe04080\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">フェイスシート編集の更新通知にも項目名(本人情報・留意点・被保険者番号等)を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フェイスシートに追加した項目(氏名・住所・電話・被保険者番号・留意点・その他関係者)が差分表(FS_FIELD_LABELS)に無く、フェイスシートで編集しても『フェイスシートの編集』に項目名が出なかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>FS_FIELD_LABELS にこれらを追加し、フェイスシート経由の編集でも『フェイスシートの編集（○○）』と項目名が出るように(既往歴は登録済み)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fe04080</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"ホーム\" data-text=\"家族・ケアマネの『利用者情報の編集』通知に変更項目名を全項目分表示変更項目名を出す差分表に生年月日・性別・介護度・被保険者番号が含まれておらず、これらだけを編集した場合は項目名が出ず『利用者情報の編集』とだけ表示されていた。差分表にこの4項目を追加し、どの項目を編集しても『利用者情報の編集（○○・○○）』のように具体名が出るように。※既存の古い通知は文言が固定のため変わりません(以後の編集から反映)。ホームb7ac04d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-07-23</span></div>\n      <p class=\"title\">家族・ケアマネの『利用者情報の編集』通知に変更項目名を全項目分表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">変更項目名を出す差分表に生年月日・性別・介護度・被保険者番号が含まれておらず、これらだけを編集した場合は項目名が出ず『利用者情報の編集』とだけ表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>差分表にこの4項目を追加し、どの項目を編集しても『利用者情報の編集（○○・○○）』のように具体名が出るように。※既存の古い通知は文言が固定のため変わりません(以後の編集から反映)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b7ac04d</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"利用者マスタ\" data-text=\"支援経過表に負担割合変更・各種更新通知・アカウント発行を自動記録支援経過表(利用者に関わる経過の記録)に、負担割合の変更やフェイスシート・利用者情報・保険証写真・アセスメントの更新、アカウント発行が載っていなかった。支援経過表は各データから毎回再生成する導出型のため、生成元(spautoevents)に『負担割合履歴・docupdates(各種更新通知)・家族/関係者アカウント』を追加。介護度/ケアマネ/サービス変更/休止/休み連絡/各種連絡/モニタリング/体力測定/担当者会議/初回報告/基本情報変更は従来どおり自動記録。利用者マスタ41deb07\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">支援経過表に負担割合変更・各種更新通知・アカウント発行を自動記録</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">支援経過表(利用者に関わる経過の記録)に、負担割合の変更やフェイスシート・利用者情報・保険証写真・アセスメントの更新、アカウント発行が載っていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>支援経過表は各データから毎回再生成する導出型のため、生成元(spAutoEvents)に『負担割合履歴・docUpdates(各種更新通知)・家族/関係者アカウント』を追加。介護度/ケアマネ/サービス変更/休止/休み連絡/各種連絡/モニタリング/体力測定/担当者会議/初回報告/基本情報変更は従来どおり自動記録。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">41deb07</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"家族アプリ\" data-text=\"削除したログインidが再利用できない不具合を修正招待セルフ登録の最終id重複チェックが古いローカルデータを参照し、他端末で削除済みのidが残っていると『事前は使える→登録でng』の矛盾になっていた。supabase有効時はsupabaseの判定を正とし、ローカルのみの重複拒否はsupabase無効時に限定。削除したidを再利用できるように。家族アプリcd60129\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">削除したログインIDが再利用できない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">招待セルフ登録の最終ID重複チェックが古いローカルデータを参照し、他端末で削除済みのIDが残っていると『事前は使える→登録でNG』の矛盾になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>Supabase有効時はSupabaseの判定を正とし、ローカルのみの重複拒否はSupabase無効時に限定。削除したIDを再利用できるように。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cd60129</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"利用者マスタ\" data-text=\"担当ケアマネ欄に登録ケアマネ(アカウント)一覧を表示(複数対応)ケアマネのアカウントを追加しても基本情報・フェイスシートに現れず、どこにも反映されないように見えた(先の緊急連絡先非表示化とも整合させる必要)。利用者に紐づくケアマネアカウント(kind=caremanager等)を担当ケアマネ欄に一覧表示。複数のケアマネも表示され、追加登録が反映される。担当(事業所/担当者)の変更は従来どおり『担当を変更』。利用者マスタc73942d\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">担当ケアマネ欄に登録ケアマネ(アカウント)一覧を表示(複数対応)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ケアマネのアカウントを追加しても基本情報・フェイスシートに現れず、どこにも反映されないように見えた(先の緊急連絡先非表示化とも整合させる必要)。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用者に紐づくケアマネアカウント(kind=caremanager等)を担当ケアマネ欄に一覧表示。複数のケアマネも表示され、追加登録が反映される。担当(事業所/担当者)の変更は従来どおり『担当を変更』。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c73942d</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"ケアマネ連携\" data-text=\"ケアマネ/家族画面の保険証等で『表示中に問題が発生しました』(familystoreid未定義)を修正子コンポーネント familypatientview が familystoreid(親familyviewで定義)を受け取っておらず、保険証(cmdocsmodal)の描画やケアマネのフェイスシート保存で familystoreid を参照した瞬間に referenceerror となり、家族/ケアマネ画面全体がエラー画面に落ちていた。pc/端末やキャッシュにより発生タイミングが違って見えた。familyview から familystoreid を prop として familypatientview へ渡すよう修正。保険証・アセスメント表示やcm保存が落ちなくなる。ケアマネ連携b2fa3d9\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">ケアマネ/家族画面の保険証等で『表示中に問題が発生しました』(familyStoreId未定義)を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">子コンポーネント FamilyPatientView が familyStoreId(親FamilyViewで定義)を受け取っておらず、保険証(CmDocsModal)の描画やケアマネのフェイスシート保存で familyStoreId を参照した瞬間に ReferenceError となり、家族/ケアマネ画面全体がエラー画面に落ちていた。PC/端末やキャッシュにより発生タイミングが違って見えた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>FamilyView から familyStoreId を prop として FamilyPatientView へ渡すよう修正。保険証・アセスメント表示やCM保存が落ちなくなる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b2fa3d9</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"家族アプリ\" data-text=\"家族・ケアマネのログインux改善(利用規約1回化・ホーム追加案内・q&amp;a・規約リンク)利用規約が毎回表示され煩わしかった。高齢者がホーム画面追加やログイン失敗時に迷いやすい。ログイン後に規約を見返す導線も無かった。利用規約の再同意を端末×ポリシー版で記録し同じ版なら二度と出さない(1回)。ログイン画面に『ホーム画面に追加する方法』(ios/android手順)と『ログインできない時(q&amp;a)』を追加。ログイン後フッターに『利用規約・プライバシーポリシー』閲覧リンクを追加。家族アプリ8cdbaab\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">家族・ケアマネのログインUX改善(利用規約1回化・ホーム追加案内・Q&amp;A・規約リンク)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用規約が毎回表示され煩わしかった。高齢者がホーム画面追加やログイン失敗時に迷いやすい。ログイン後に規約を見返す導線も無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用規約の再同意を端末×ポリシー版で記録し同じ版なら二度と出さない(1回)。ログイン画面に『ホーム画面に追加する方法』(iOS/Android手順)と『ログインできない時(Q&amp;A)』を追加。ログイン後フッターに『利用規約・プライバシーポリシー』閲覧リンクを追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8cdbaab</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"家族アプリ\" data-text=\"アカウント管理の操作ボタン潰れを修正＋エラー画面に原因表示アカウント一覧の操作ボタンが col-span-1(約8%幅)に押し込まれ、スマホで潰れて見切れていた。また画面エラー時に原因が極薄色で読めなかった。操作ボタンにラベル(id編集/印刷/削除)を付け、スマホでは縦積みに(grid 4+3+2+3)。エラー画面は原因(スタック)を読める色で表示。家族アプリa4f60c9\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">アカウント管理の操作ボタン潰れを修正＋エラー画面に原因表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">アカウント一覧の操作ボタンが col-span-1(約8%幅)に押し込まれ、スマホで潰れて見切れていた。また画面エラー時に原因が極薄色で読めなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>操作ボタンにラベル(ID編集/印刷/削除)を付け、スマホでは縦積みに(grid 4+3+2+3)。エラー画面は原因(スタック)を読める色で表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a4f60c9</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"利用者マスタ\" data-text=\"緊急連絡先: ケアマネを非表示化＋フェイスシートでの削除が反映されない不具合を修正①主要連絡先がケアマネ(続柄=ケアマネ等)でも緊急連絡先に表示されていた。②フェイスシートで連絡先を削除して保存しても、既存へのupsert(追加更新)のみで削除されず、墓石も無いため同期で復活していた。①主要連絡先がケアマネ由来なら緊急連絡先に出さない。②家族連絡先はフェイスシートの編集結果で置き換え(削除を反映)、ケアマネ連絡先は保持。削除分は墓石(_deletedec)に記録し同期でも復活させない。利用者マスタ725a3fd\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">緊急連絡先: ケアマネを非表示化＋フェイスシートでの削除が反映されない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">①主要連絡先がケアマネ(続柄=ケアマネ等)でも緊急連絡先に表示されていた。②フェイスシートで連絡先を削除して保存しても、既存へのupsert(追加更新)のみで削除されず、墓石も無いため同期で復活していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>①主要連絡先がケアマネ由来なら緊急連絡先に出さない。②家族連絡先はフェイスシートの編集結果で置き換え(削除を反映)、ケアマネ連絡先は保持。削除分は墓石(_deletedEC)に記録し同期でも復活させない。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">725a3fd</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"ケアマネ連携\" data-text=\"pdf/画像プレビューの×ボタンを見やすく＋pdfのボタン重複を解消×閉じるボタンが半透明の白で、白いpdf面の上だと見えなかった。またpdf時に『ダウンロード』と『別タブで開く』が重複していた。×ボタンを赤・白枠・影で明確化(最前面)。pdfは『別タブで開く』のみ、画像は『ダウンロード』のみ表示に整理。ケアマネ連携fb510e8\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">PDF/画像プレビューの×ボタンを見やすく＋PDFのボタン重複を解消</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">×閉じるボタンが半透明の白で、白いPDF面の上だと見えなかった。またPDF時に『ダウンロード』と『別タブで開く』が重複していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>×ボタンを赤・白枠・影で明確化(最前面)。PDFは『別タブで開く』のみ、画像は『ダウンロード』のみ表示に整理。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">fb510e8</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"その他関係者(訪問看護等)もフェイスシートへ一本化その他関係者だけ利用者マスタで編集する形が残り、他項目(氏名・連絡先・介護保険)をフェイスシートへ一本化した方針と不揃いだった。フェイスシートに『その他関係者』の編集枠(追加/削除・氏名/種別/事業所/電話/fax)を新設し、保存で利用者本体へ反映(事業所・ケアマネ両経路)。利用者マスタ基本情報のその他関係者は表形式(表示のみ)＋『フェイスシートで編集』に。利用者マスタ8f0483a\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">その他関係者(訪問看護等)もフェイスシートへ一本化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">その他関係者だけ利用者マスタで編集する形が残り、他項目(氏名・連絡先・介護保険)をフェイスシートへ一本化した方針と不揃いだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>フェイスシートに『その他関係者』の編集枠(追加/削除・氏名/種別/事業所/電話/FAX)を新設し、保存で利用者本体へ反映(事業所・ケアマネ両経路)。利用者マスタ基本情報のその他関係者は表形式(表示のみ)＋『フェイスシートで編集』に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">8f0483a</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"ケアマネ連携\" data-text=\"ケアマネ側で事業所が添付したpdf(保険証・負担割合証)が見れない不具合を修正事業所がアップロードしたpdfは type=&#x27;application/pdf&#x27; で保存されるが、ケアマネ画面のファイル表示は type===&#x27;pdf&#x27;(完全一致)で判定していたため、事業所pdfが画像扱いになり壊れて表示されていた(ケアマネ自身がアップした分は type=&#x27;pdf&#x27; のため見れていた)。加えて data uri のpdfはブラウザがiframe/別タブでブロックする。ファイル表示・プレビューのpdf判定を『type部分一致 または .pdf名』に堅牢化。data uri のpdfは blob url に変換して表示し、『別タブで開く』ボタンも追加。事業所・ケアマネのどちらが添付したpdfも双方で閲覧可能に。ケアマネ連携52590d4\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">ケアマネ側で事業所が添付したPDF(保険証・負担割合証)が見れない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">事業所がアップロードしたPDFは type=&#x27;application/pdf&#x27; で保存されるが、ケアマネ画面のファイル表示は type===&#x27;pdf&#x27;(完全一致)で判定していたため、事業所PDFが画像扱いになり壊れて表示されていた(ケアマネ自身がアップした分は type=&#x27;pdf&#x27; のため見れていた)。加えて data URI のPDFはブラウザがiframe/別タブでブロックする。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ファイル表示・プレビューのPDF判定を『type部分一致 または .pdf名』に堅牢化。data URI のPDFは Blob URL に変換して表示し、『別タブで開く』ボタンも追加。事業所・ケアマネのどちらが添付したPDFも双方で閲覧可能に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">52590d4</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"基本情報の並び調整＋担当ケアマネ・緊急連絡先も表形式に統一介護保険の期間が値と離れて分かりにくく、担当ケアマネ・緊急連絡先だけ従来の入力欄形式で見た目が不揃いだった。介護度の直下に認定有効期間、負担割合の直下に負担割合の有効期間を配置。担当ケアマネは表形式(表示のみ)＋『担当を変更』ボタン(履歴付きモーダル)、緊急連絡先は表形式(主要＋追加をまとめて表示)＋『フェイスシートで編集』に統一。利用者マスタ5177da2\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">基本情報の並び調整＋担当ケアマネ・緊急連絡先も表形式に統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">介護保険の期間が値と離れて分かりにくく、担当ケアマネ・緊急連絡先だけ従来の入力欄形式で見た目が不揃いだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>介護度の直下に認定有効期間、負担割合の直下に負担割合の有効期間を配置。担当ケアマネは表形式(表示のみ)＋『担当を変更』ボタン(履歴付きモーダル)、緊急連絡先は表形式(主要＋追加をまとめて表示)＋『フェイスシートで編集』に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5177da2</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"利用者マスタ基本情報(表示のみ)を表形式に変更し見やすく表示のみ化した基本情報が「ラベル 値／ラベル 値」の2列詰めで、項目が追いづらく見づらかった。ラベル＝左(薄い背景)／値＝右の行(表)形式に統一(氏名・介護保険・住所連絡先の各カード)。罫線区切りで一覧性を向上。利用者マスタa191a33\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">利用者マスタ基本情報(表示のみ)を表形式に変更し見やすく</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">表示のみ化した基本情報が「ラベル 値／ラベル 値」の2列詰めで、項目が追いづらく見づらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ラベル＝左(薄い背景)／値＝右の行(表)形式に統一(氏名・介護保険・住所連絡先の各カード)。罫線区切りで一覧性を向上。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a191a33</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"利用者マスタ\" data-text=\"利用者マスタ基本情報を表示のみ化し、編集をフェイスシート／個人ファイルへ一本化(仕上げ)氏名・住所・連絡先・被保険者番号・介護保険が複数画面で編集でき『どこで入力するか』が分かりにくかった。編集場所が一本化されれば、慣れない人でも迷わず、二重編集の巻き戻りも防げる。利用者マスタ基本情報の 氏名/フリガナ/性別/生年月日・住所/電話/メール・被保険者番号 を表示のみに。各ブロックの『フェイスシートで編集』で個人ファイルのフェイスシートを自動オープン、介護度・負担割合・認定期間は『個人ファイルで編集』で保険証/負担割合証へジャンプ。運用項目(利用状態・利用開始/終了日・担当ケアマネ)はマスタで編集可のまま。利用者マスタd8e377f\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">利用者マスタ基本情報を表示のみ化し、編集をフェイスシート／個人ファイルへ一本化(仕上げ)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">氏名・住所・連絡先・被保険者番号・介護保険が複数画面で編集でき『どこで入力するか』が分かりにくかった。編集場所が一本化されれば、慣れない人でも迷わず、二重編集の巻き戻りも防げる。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用者マスタ基本情報の 氏名/フリガナ/性別/生年月日・住所/電話/メール・被保険者番号 を表示のみに。各ブロックの『フェイスシートで編集』で個人ファイルのフェイスシートを自動オープン、介護度・負担割合・認定期間は『個人ファイルで編集』で保険証/負担割合証へジャンプ。運用項目(利用状態・利用開始/終了日・担当ケアマネ)はマスタで編集可のまま。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">d8e377f</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"利用者マスタ\" data-text=\"フェイスシートを利用者情報の編集ハブ化(本人情報・被保険者番号・留意点を編集可＋誰が編集しても1箇所に反映)氏名・住所・電話・被保険者番号等が利用者マスタでしか編集できず、フェイスシート・個人ファイルとの役割が曖昧だった。事業所・ケアマネ・家族が別々の画面で編集し、どこが正か分かりにくい。フェイスシートで氏名/フリガナ/生年月日/性別/住所/電話/メール/被保険者番号/留意点を編集可能にし、保存時に利用者本体へ書き戻す(事業所・ケアマネ両経路)。誰が編集しても最終反映先は利用者本体の1箇所に統一。あわせて保険証・負担割合証の期間入力を和暦のみ(西暦カレンダー廃止)に。※マスタ側の該当項目を表示のみにする対応は次段階。利用者マスタ02ecdb6\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">フェイスシートを利用者情報の編集ハブ化(本人情報・被保険者番号・留意点を編集可＋誰が編集しても1箇所に反映)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">氏名・住所・電話・被保険者番号等が利用者マスタでしか編集できず、フェイスシート・個人ファイルとの役割が曖昧だった。事業所・ケアマネ・家族が別々の画面で編集し、どこが正か分かりにくい。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>フェイスシートで氏名/フリガナ/生年月日/性別/住所/電話/メール/被保険者番号/留意点を編集可能にし、保存時に利用者本体へ書き戻す(事業所・ケアマネ両経路)。誰が編集しても最終反映先は利用者本体の1箇所に統一。あわせて保険証・負担割合証の期間入力を和暦のみ(西暦カレンダー廃止)に。※マスタ側の該当項目を表示のみにする対応は次段階。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">02ecdb6</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"介護保険・負担割合の適用期間の表示を和暦に統一適用期間・変更履歴が西暦(2026/4/1等)表示で、介護保険証・負担割合証の実物(和暦)と突き合わせづらかった。マスタ基本情報の認定有効期間・負担割合の有効期間の表示、および変更履歴(valuehistorylist)の期間表示を和暦(令和8年4月1日等)に変更。利用者マスタc146458\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護保険・負担割合の適用期間の表示を和暦に統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">適用期間・変更履歴が西暦(2026/4/1等)表示で、介護保険証・負担割合証の実物(和暦)と突き合わせづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マスタ基本情報の認定有効期間・負担割合の有効期間の表示、および変更履歴(ValueHistoryList)の期間表示を和暦(令和8年4月1日等)に変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c146458</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"介護保険(介護度・負担割合・認定期間)の編集を個人ファイルへ一本化(マスタ基本情報は表示のみ＋ジャンプ)同じ介護度・負担割合・認定期間が『利用者マスタの基本情報』と『個人ファイル』の両方で編集でき、どちらで入力するか分かりにくく、二重編集による巻き戻りの温床でもあった。証の写真は個人ファイルにしか貼れない。マスタ基本情報では介護度・負担割合・認定有効期間を表示のみにし、『個人ファイルで編集』ボタンで個人ファイル(保険証・負担割合証)へジャンプ＋該当セクションへ自動スクロール。編集場所を個人ファイルに一本化(写真と同じ場所で管理)。被保険者番号は個人ファイルに編集欄が無いためマスタ編集のまま残置。氏名・住所・電話等の個人ファイルへの移設は編集ui新設が必要なため次段階。利用者マスタ2f6fcac\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護保険(介護度・負担割合・認定期間)の編集を個人ファイルへ一本化(マスタ基本情報は表示のみ＋ジャンプ)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同じ介護度・負担割合・認定期間が『利用者マスタの基本情報』と『個人ファイル』の両方で編集でき、どちらで入力するか分かりにくく、二重編集による巻き戻りの温床でもあった。証の写真は個人ファイルにしか貼れない。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マスタ基本情報では介護度・負担割合・認定有効期間を表示のみにし、『個人ファイルで編集』ボタンで個人ファイル(保険証・負担割合証)へジャンプ＋該当セクションへ自動スクロール。編集場所を個人ファイルに一本化(写真と同じ場所で管理)。被保険者番号は個人ファイルに編集欄が無いためマスタ編集のまま残置。氏名・住所・電話等の個人ファイルへの移設は編集UI新設が必要なため次段階。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2f6fcac</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"個人ファイルの介護保険証・負担割合証を「選択即保存」から「保存ボタンで確定」に個人ファイル(利用者を開いた詳細画面)の保険証(介護度・認定有効期間)/負担割合証(負担割合・有効期間)は、プルダウンや日付を選んだ瞬間に利用者マスタへ自動保存・履歴記録されていた。期間を決める前の暫定選択がそのまま確定してしまう。選択・期間変更は下書きに溜め、『保存』ボタンを押したときだけ確定(取消可)する方式に変更。従来のインライン自動保存を廃止。※前回の対応は利用者マスタ管理の別レイアウト側で、実際に使う個人ファイル側に未反映だったのを修正。利用者マスタa1dd0d3\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">個人ファイルの介護保険証・負担割合証を「選択即保存」から「保存ボタンで確定」に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">個人ファイル(利用者を開いた詳細画面)の保険証(介護度・認定有効期間)/負担割合証(負担割合・有効期間)は、プルダウンや日付を選んだ瞬間に利用者マスタへ自動保存・履歴記録されていた。期間を決める前の暫定選択がそのまま確定してしまう。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>選択・期間変更は下書きに溜め、『保存』ボタンを押したときだけ確定(取消可)する方式に変更。従来のインライン自動保存を廃止。※前回の対応は利用者マスタ管理の別レイアウト側で、実際に使う個人ファイル側に未反映だったのを修正。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a1dd0d3</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"各種設定\" data-text=\"一括削除の「重複候補」に統合機能を追加（記録を残す1人へ引き継ぐ）利用者マスタの「重複」ボタン(統合)を各種設定へ集約するにあたり、各種設定側は削除しかできなかった。両方に記録がある重複を安全に1人へまとめる手段が必要だった。重複候補を同名でグループ化し、グループごとに『残す1人』をラジオで選んで統合できるように。統合すると他の重複の記録(提供記録・シフト・写真等)を残す人へ付け替え、空欄も補完してから重複を削除する(記録は失われない)。記録件数を各行に表示し、既定は記録が最も多い人を残す。各種設定188b16e\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">一括削除の「重複候補」に統合機能を追加（記録を残す1人へ引き継ぐ）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">利用者マスタの「重複」ボタン(統合)を各種設定へ集約するにあたり、各種設定側は削除しかできなかった。両方に記録がある重複を安全に1人へまとめる手段が必要だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>重複候補を同名でグループ化し、グループごとに『残す1人』をラジオで選んで統合できるように。統合すると他の重複の記録(提供記録・シフト・写真等)を残す人へ付け替え、空欄も補完してから重複を削除する(記録は失われない)。記録件数を各行に表示し、既定は記録が最も多い人を残す。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">188b16e</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"介護度の適用期間を「変更ボタン→ポップアップ→保存」方式に変更（重複ボタンは各種設定へ集約し削除）直前の対応(下書き＋小さな保存ボタン)は、編集→保存の手数が多く分かりやすくなかった。また利用者マスタの「重複」統合は各種設定の一括削除(重複候補)へ機能を集約した。介護度の適用期間は、現在の期間を表示し「適用期間を変更」ボタンでポップアップを開き、介護度・開始日/終了日を選んで保存する方式に統一(負担割合・介護度変更と同じ操作感。期間の訂正では履歴を増やさない)。利用者マスタの「重複」ボタンは削除。利用者マスタ3002443\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護度の適用期間を「変更ボタン→ポップアップ→保存」方式に変更（重複ボタンは各種設定へ集約し削除）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">直前の対応(下書き＋小さな保存ボタン)は、編集→保存の手数が多く分かりやすくなかった。また利用者マスタの「重複」統合は各種設定の一括削除(重複候補)へ機能を集約した。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>介護度の適用期間は、現在の期間を表示し「適用期間を変更」ボタンでポップアップを開き、介護度・開始日/終了日を選んで保存する方式に統一(負担割合・介護度変更と同じ操作感。期間の訂正では履歴を増やさない)。利用者マスタの「重複」ボタンは削除。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3002443</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"各種設定\" data-text=\"利用者・ケアマネ事業所の一括削除が管理者以外でも操作できた問題を修正「管理者用」と表示しつつ、実際の表示条件が isadmin(=管理者に加えmanager職も含む)だったため、管理者以外のログインでも一括削除が使えてしまっていた。介護記録に紐づく重要データを消せる画面のため危険だった。ログイン情報カード等と同じ canadmin(管理者パスワード認証済み / super_admin / 管理者未設定時のみ)に統一。管理者以外には操作させず、未認証時は『管理者のみ』ゲート＋認証ボタンを表示する。各種設定0cb6b26\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">各種設定</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">利用者・ケアマネ事業所の一括削除が管理者以外でも操作できた問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「管理者用」と表示しつつ、実際の表示条件が isAdmin(=管理者に加えmanager職も含む)だったため、管理者以外のログインでも一括削除が使えてしまっていた。介護記録に紐づく重要データを消せる画面のため危険だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>ログイン情報カード等と同じ canAdmin(管理者パスワード認証済み / super_admin / 管理者未設定時のみ)に統一。管理者以外には操作させず、未認証時は『管理者のみ』ゲート＋認証ボタンを表示する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0cb6b26</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"各種設定\" data-text=\"一括削除に「重複候補」フィルタを追加(重複利用者の削除)氏名が同じ重複利用者(csv取込の二重登録等)を、利用者マスタの統合とは別に、まとめて確認・削除する手段が各種設定側に無かった。一括削除の利用者一覧に『重複候補』フィルタ(同名2件以上)を追加。各行に記録件数と重複バッジを表示し、記録0件の重複を選んで削除できるようにした。両方に記録がある場合は記録が消えるため、利用者マスタの『重複』統合(記録引き継ぎ)を案内。各種設定0cb6b26\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">一括削除に「重複候補」フィルタを追加(重複利用者の削除)</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">氏名が同じ重複利用者(CSV取込の二重登録等)を、利用者マスタの統合とは別に、まとめて確認・削除する手段が各種設定側に無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>一括削除の利用者一覧に『重複候補』フィルタ(同名2件以上)を追加。各行に記録件数と重複バッジを表示し、記録0件の重複を選んで削除できるようにした。両方に記録がある場合は記録が消えるため、利用者マスタの『重複』統合(記録引き継ぎ)を案内。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">0cb6b26</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"介護度の適用期間も選択即保存をやめ、確定ボタン方式に介護度の適用期間(カレンダー)を編集すると、確定前でも1.5秒後に自動保存され、暫定の期間がそのまま全端末へ反映されていた。期間は下書きに溜め、『この期間で保存』を押したときだけ保存する方式に変更(負担割合と同じ考え方)。取消もできる。利用者マスタ88ee804\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">介護度の適用期間も選択即保存をやめ、確定ボタン方式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">介護度の適用期間(カレンダー)を編集すると、確定前でも1.5秒後に自動保存され、暫定の期間がそのまま全端末へ反映されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>期間は下書きに溜め、『この期間で保存』を押したときだけ保存する方式に変更(負担割合と同じ考え方)。取消もできる。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">88ee804</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"提供記録\" data-text=\"「元に戻す」でokしても記録が画面に反映されない不具合を修正復元は onsave で提供記録を更新するが、提供記録入力(recordview)の画面用データを作り直すエフェクトに「同じ日付で編集中(dirty)なら作り直さない」ガードがあり、復元が編集中フラグを落とさないため、データは復元されているのに画面が復元前のまま(=戻したのに変わらない)になっていた。復元の適用後に編集中フラグ(dirtyref)を落とし、必ず画面を作り直すようにした。これで選んだ時点の内容が即座に画面へ反映される。提供記録2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">「元に戻す」でOKしても記録が画面に反映されない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">復元は onSave で提供記録を更新するが、提供記録入力(RecordView)の画面用データを作り直すエフェクトに「同じ日付で編集中(dirty)なら作り直さない」ガードがあり、復元が編集中フラグを落とさないため、データは復元されているのに画面が復元前のまま(=戻したのに変わらない)になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>復元の適用後に編集中フラグ(dirtyRef)を落とし、必ず画面を作り直すようにした。これで選んだ時点の内容が即座に画面へ反映される。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"ipad等で利用者マスタの右端が見切れる問題を修正画面は横1100px設計を前提にzoom縮小して各端末に合わせているが、利用者マスタは最大1800px・340px固定リスト＋多列で、ipad(縦810/横1080px)では実画面幅で多列レイアウトが発火して1100pxの枠をはみ出し、下までスクロールすると右端が切れていた。利用者マスタをzoom縮小の対象から外し、実際の画面幅で素直に折り返す方式に変更(pcは従来どおり)。端末ごとに画面領域へ収まるようにした。利用者マスタ2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">iPad等で利用者マスタの右端が見切れる問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">画面は横1100px設計を前提にzoom縮小して各端末に合わせているが、利用者マスタは最大1800px・340px固定リスト＋多列で、iPad(縦810/横1080px)では実画面幅で多列レイアウトが発火して1100pxの枠をはみ出し、下までスクロールすると右端が切れていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>利用者マスタをzoom縮小の対象から外し、実際の画面幅で素直に折り返す方式に変更(PCは従来どおり)。端末ごとに画面領域へ収まるようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"負担割合をプルダウン選択した瞬間に保存されるのをやめ、確定ボタン方式に負担割合を選ぶと(適用期間を決める前でも)1.5秒後に自動でクラウド保存され、暫定選択がそのまま確定・全端末へ反映されてしまっていた。介護度と同じく、選択したら確認モーダルを開き、適用開始日/終了日を指定して「確定」を押したときだけ保存する方式に統一。誤選択がそのまま保存されないようにした。利用者マスタ2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">負担割合をプルダウン選択した瞬間に保存されるのをやめ、確定ボタン方式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">負担割合を選ぶと(適用期間を決める前でも)1.5秒後に自動でクラウド保存され、暫定選択がそのまま確定・全端末へ反映されてしまっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>介護度と同じく、選択したら確認モーダルを開き、適用開始日/終了日を指定して「確定」を押したときだけ保存する方式に統一。誤選択がそのまま保存されないようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"ホーム\" data-text=\"ホームの「家族・ケアマネからの更新」に、変更した項目名を表示家族・ケアマネが利用者情報を編集した通知が『利用者情報の編集』としか出ず、どこを直したのか分からなかった。編集前後を項目単位で比較し『利用者情報の編集（電話番号・住所 ほか）』のように変更項目名を表示(最大8件＋ほかn項目)。ホーム2ce8504\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ホーム</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">ホームの「家族・ケアマネからの更新」に、変更した項目名を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">家族・ケアマネが利用者情報を編集した通知が『利用者情報の編集』としか出ず、どこを直したのか分からなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>編集前後を項目単位で比較し『利用者情報の編集（電話番号・住所 ほか）』のように変更項目名を表示(最大8件＋ほかN項目)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">2ce8504</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"提供記録\" data-text=\"「元に戻す」の確認に、現在クラウド上の最新の端末・時刻を表示復元(元に戻す)は全端末へ「最新」として反映され、他端末の新しい入力を上書きしうる。従来の確認文は一般的な注意のみで、いま実際に誰が最新なのかが分からず、上書きの判断がしづらかった。確認ダイアログに _lastsync から「現在の最新: 『端末名』が 〇時 に更新」を常時表示。さらに、この復元スナップショットより後に別の端末が更新している場合のみ『⚠ この履歴より新しい更新が別端末にあります。復元すると上書きされます』を追加表示(自分が最新なら余計な警告は出さない)。提供記録a4f3d28\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">「元に戻す」の確認に、現在クラウド上の最新の端末・時刻を表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">復元(元に戻す)は全端末へ「最新」として反映され、他端末の新しい入力を上書きしうる。従来の確認文は一般的な注意のみで、いま実際に誰が最新なのかが分からず、上書きの判断がしづらかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>確認ダイアログに _lastSync から「現在の最新: 『端末名』が 〇時 に更新」を常時表示。さらに、この復元スナップショットより後に別の端末が更新している場合のみ『⚠ この履歴より新しい更新が別端末にあります。復元すると上書きされます』を追加表示(自分が最新なら余計な警告は出さない)。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a4f3d28</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"各種設定\" data-text=\"端末名の設定と「最終更新した端末」の表示を追加複数の端末(pc・ipad等)で使うと、今どの端末の入力が最新か分からず、古い端末で上書きしていないか不安があった。以前検討した「入力ロック」は現場運用の妨げになるため見送り、代わりに『誰が最後に更新したか』を可視化する方針にした。各種設定＞システムに「この端末の名前」欄を追加(端末ごとにlocalstorageへ保存。他端末には送信しない)。記録の保存時に「最終更新した端末名・時刻」を全端末共有の _lastsync に記録し、画面上部ヘッダーと設定画面に常時表示。最終更新が自端末なら緑「この端末の内容が最新です」、別端末なら青「最新の更新は〇〇で行われました(この端末にも反映済み)」を表示。ヘッダーの表示をタップすると設定の端末名欄へジャンプ。各種設定c44b757\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-22</span></div>\n      <p class=\"title\">端末名の設定と「最終更新した端末」の表示を追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">複数の端末(PC・iPad等)で使うと、今どの端末の入力が最新か分からず、古い端末で上書きしていないか不安があった。以前検討した「入力ロック」は現場運用の妨げになるため見送り、代わりに『誰が最後に更新したか』を可視化する方針にした。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各種設定＞システムに「この端末の名前」欄を追加(端末ごとにlocalStorageへ保存。他端末には送信しない)。記録の保存時に「最終更新した端末名・時刻」を全端末共有の _lastSync に記録し、画面上部ヘッダーと設定画面に常時表示。最終更新が自端末なら緑「この端末の内容が最新です」、別端末なら青「最新の更新は〇〇で行われました(この端末にも反映済み)」を表示。ヘッダーの表示をタップすると設定の端末名欄へジャンプ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c44b757</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"同期\" data-text=\"操作ログ同期の切替で提供記録の保存先が一時的に失われた不具合を修正し、段階導入へ変更差分を作る処理が参照していた変数 prev がスコープ外にあり referenceerror となって、操作が1件も作られていなかった(診断ログ ops-diff-error &quot;prev is not defined&quot; で判明)。にもかかわらず巨大json側の ticketrecords を先に凍結していたため、「新方式は動かない×旧方式も止めてある」という状態になり、その間の提供記録の保存がクラウドのどこにも書かれなかった。切替を一度に行ったこと自体が設計判断の誤り。差分の直前状態を appdata から取得するよう修正。oplog_frozen_keys を空に戻して巨大json方式を再有効化し、新方式が動かなくても必ず保存される二重の保険とした。さらに oplog_apply フラグを追加し、第1段は「操作ログへの送信のみ」を本番で走らせる方式に変更。受信適用と旧方式の凍結は、送信の安定をログで確認してから第2段でまとめて有効化する。同期703dd4c\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">操作ログ同期の切替で提供記録の保存先が一時的に失われた不具合を修正し、段階導入へ変更</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">差分を作る処理が参照していた変数 prev がスコープ外にあり ReferenceError となって、操作が1件も作られていなかった(診断ログ ops-diff-error &quot;prev is not defined&quot; で判明)。にもかかわらず巨大JSON側の ticketRecords を先に凍結していたため、「新方式は動かない×旧方式も止めてある」という状態になり、その間の提供記録の保存がクラウドのどこにも書かれなかった。切替を一度に行ったこと自体が設計判断の誤り。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>差分の直前状態を appData から取得するよう修正。OPLOG_FROZEN_KEYS を空に戻して巨大JSON方式を再有効化し、新方式が動かなくても必ず保存される二重の保険とした。さらに OPLOG_APPLY フラグを追加し、第1段は「操作ログへの送信のみ」を本番で走らせる方式に変更。受信適用と旧方式の凍結は、送信の安定をログで確認してから第2段でまとめて有効化する。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">703dd4c</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"同期\" data-text=\"提供記録を操作ログ同期へ接続（送信・受信・リベース・凍結の実装）巨大jsonの往復方式では、2端末での編集時にマージの勝ち負けで入力が消える問題が構造的に解消できないため。保存時に変わった項目だけを差分化してindexeddbへ永続化し sync_ops へ送信、ackが返った分だけキューから削除。受信はrealtime＋5秒ポーリングで差分取得。適用は必ず「受信分＋自分の未送信分」の順で畳み込み(リベース)、他端末の更新を受けた瞬間に入力途中が消えないようにした。初回取得はページングで全件取得。差分化と適用の純関数を28ケースで検証。同期ec97394\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">提供記録を操作ログ同期へ接続（送信・受信・リベース・凍結の実装）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">巨大JSONの往復方式では、2端末での編集時にマージの勝ち負けで入力が消える問題が構造的に解消できないため。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>保存時に変わった項目だけを差分化してIndexedDBへ永続化し sync_ops へ送信、ACKが返った分だけキューから削除。受信はRealtime＋5秒ポーリングで差分取得。適用は必ず「受信分＋自分の未送信分」の順で畳み込み(リベース)、他端末の更新を受けた瞬間に入力途中が消えないようにした。初回取得はページングで全件取得。差分化と適用の純関数を28ケースで検証。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ec97394</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"同期\" data-text=\"同期方式の刷新に着手（操作ログ方式）：基盤モジュールとdbマイグレーションを用意時計補正・押し戻し遮断の修正後も同期停止が再発。根本原因は「アプリ全体の巨大jsonを1.2秒ごとに丸ごと送り合い、端末の時計でマージの勝敗を決めている」という構造そのものにある。加えて送信キューもackも無いため、iosの通信サスペンドで失われた送信は永久に失われる。「変更した項目だけを送る」操作ログ方式へ移行する。src/lib/syncops.js を新設（送信未確定キューをindexeddbに永続化／push_sync_ops rpcへの送信とackによるキュー削除／revision差分取得とrealtime購読／操作を状態へ畳み込む純関数applyops）。順序はpostgresのbigserial採番が決めるため端末の時計に一切依存しない。純関数部分を18ケース（項目更新・入れ子・新規作成・深い階層・二次元マップ・空文字・レコード削除・set→deleteの順序・リベース・後勝ち・参照維持）で検証済み。dbマイグレーションsql（sync_opsテーブル／push_sync_ops rpc／rls／realtime有効化。追加のみ・非破壊）を sql/2026-07-20_sync_ops_phase1.sql に用意。現時点ではアプリ本体から未接続のため動作に影響なし。外部レビュー（gemini提案書）のうち「クライアント代表がスナップショットを上書きする」案は今回の事故と同じ構造のため不採用とし、db側で畳み込む方式に変更した。同期a041567 / f08a148\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">同期方式の刷新に着手（操作ログ方式）：基盤モジュールとDBマイグレーションを用意</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">時計補正・押し戻し遮断の修正後も同期停止が再発。根本原因は「アプリ全体の巨大JSONを1.2秒ごとに丸ごと送り合い、端末の時計でマージの勝敗を決めている」という構造そのものにある。加えて送信キューもACKも無いため、iOSの通信サスペンドで失われた送信は永久に失われる。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>「変更した項目だけを送る」操作ログ方式へ移行する。src/lib/syncOps.js を新設（送信未確定キューをIndexedDBに永続化／push_sync_ops RPCへの送信とACKによるキュー削除／revision差分取得とRealtime購読／操作を状態へ畳み込む純関数applyOps）。順序はPostgresのbigserial採番が決めるため端末の時計に一切依存しない。純関数部分を18ケース（項目更新・入れ子・新規作成・深い階層・二次元マップ・空文字・レコード削除・SET→DELETEの順序・リベース・後勝ち・参照維持）で検証済み。DBマイグレーションSQL（sync_opsテーブル／push_sync_ops RPC／RLS／Realtime有効化。追加のみ・非破壊）を sql/2026-07-20_sync_ops_phase1.sql に用意。現時点ではアプリ本体から未接続のため動作に影響なし。外部レビュー（Gemini提案書）のうち「クライアント代表がスナップショットを上書きする」案は今回の事故と同じ構造のため不採用とし、DB側で畳み込む方式に変更した。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a041567 / f08a148</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"同期\" data-text=\"未同期バナーを撤去し、原因特定用の同期診断ログを追加未同期警告バナーが誤検知で常時表示され作業の邪魔になっていた。また、時計補正と押し戻しループの修正後も同期が止まる事象が再発したが、ipadではブラウザのコンソールが見られず原因を特定する手段が無かった。バナーの画面表示を廃止(検知自体は継続しログにのみ記録)。localstorageに直近120件の同期イベント(save/pull/pull-preserve/push-ok/push-fail/cas-conflict/clock-adjust/stall)を記録し、urlに ?syncdebug=1 を付けて開くと右下に同期ログパネルを表示できるようにした。再現時のログから、保存が発火しているか・クラウドへ届いているか・競合で失敗しているかを切り分ける。同期edbe195\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">未同期バナーを撤去し、原因特定用の同期診断ログを追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">未同期警告バナーが誤検知で常時表示され作業の邪魔になっていた。また、時計補正と押し戻しループの修正後も同期が止まる事象が再発したが、iPadではブラウザのコンソールが見られず原因を特定する手段が無かった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>バナーの画面表示を廃止(検知自体は継続しログにのみ記録)。localStorageに直近120件の同期イベント(save/pull/pull-preserve/push-ok/push-fail/cas-conflict/clock-adjust/stall)を記録し、URLに ?syncdebug=1 を付けて開くと右下に同期ログパネルを表示できるようにした。再現時のログから、保存が発火しているか・クラウドへ届いているか・競合で失敗しているかを切り分ける。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">edbe195</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"同期\" data-text=\"他端末の入力をクラウドから消し戻し続けるループを遮断pull(4秒ごと)の「端末内の記録を保持する」処理が、『端末内の_savedatがクラウドより新しい』というだけで記録を丸ごとクラウドへ押し戻していた。時計が進んだ端末ではこの条件が常に成立するため、他端末が入力するたびに4秒後に古い内容で上書きし直すループになり、同期が止まったように見えていた。さらに双方が押し合うことで楽観ロック(cas)の競合が増え、既定5回の再試行を使い切って保存自体が失敗することもあった。再送(push)するのは「クラウドに存在しない記録があるとき」＝pushが本当に届いていない場合だけに限定。クラウドにも存在する記録の新旧判定は、項目単位でマージする通常の保存経路に任せる。あわせて通常保存のcas再試行を5→8回に増強。保持・墓石・クラウド優先の各挙動は6ケースで回帰検証済み。同期1118876\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">他端末の入力をクラウドから消し戻し続けるループを遮断</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">pull(4秒ごと)の「端末内の記録を保持する」処理が、『端末内の_savedAtがクラウドより新しい』というだけで記録を丸ごとクラウドへ押し戻していた。時計が進んだ端末ではこの条件が常に成立するため、他端末が入力するたびに4秒後に古い内容で上書きし直すループになり、同期が止まったように見えていた。さらに双方が押し合うことで楽観ロック(CAS)の競合が増え、既定5回の再試行を使い切って保存自体が失敗することもあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>再送(push)するのは「クラウドに存在しない記録があるとき」＝pushが本当に届いていない場合だけに限定。クラウドにも存在する記録の新旧判定は、項目単位でマージする通常の保存経路に任せる。あわせて通常保存のCAS再試行を5→8回に増強。保持・墓石・クラウド優先の各挙動は6ケースで回帰検証済み。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">1118876</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"同期\" data-text=\"端末間の時計ズレで同期が止まり、入力が消える不具合を恒久修正同期のマージは記録の _savedat / _fieldts（保存時刻）が新しい方を採用する方式だが、この時刻は各端末の date.now()＝端末の時計そのものだった。pcの時計がipadより進んでいると、ipadで入力した内容は常に「古い」と判定されてマージで捨てられる。画面上はエラーも出ないため同期が止まったように見え、再読み込みするとクラウドの古い内容に戻って入力が消える。長文入力ほど同一項目を上書きし続けるため発症しやすかった。同期専用の単調時計(lamport clock)を導入。app_state に __clock（そのデータの最大同期時刻）を持たせ、クラウドを読むたびに自端末のオフセットを引き上げて「クラウドで見た最新より必ず新しい時刻」を刻むようにした。これで端末の時計がずれていても後から行った入力が必ず勝つ。__clock を持たない既存データは記録の _savedat 最大値から初期化。400日以上先の異常な時刻は取り込まない安全弁つき。あわせて _savedat/_fieldts/_updatedat の刻印を全26箇所で新方式に統一。さらに、ローカル編集から20秒以上クラウド保存が成功していない場合は画面上部に「⚠ クラウドに保存できていません（n秒未同期）」＋「今すぐ再送」を常時表示し、同期停止が無表示のまま続かないようにした。同期18fda72\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">端末間の時計ズレで同期が止まり、入力が消える不具合を恒久修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同期のマージは記録の _savedAt / _fieldTs（保存時刻）が新しい方を採用する方式だが、この時刻は各端末の Date.now()＝端末の時計そのものだった。PCの時計がiPadより進んでいると、iPadで入力した内容は常に「古い」と判定されてマージで捨てられる。画面上はエラーも出ないため同期が止まったように見え、再読み込みするとクラウドの古い内容に戻って入力が消える。長文入力ほど同一項目を上書きし続けるため発症しやすかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同期専用の単調時計(Lamport clock)を導入。app_state に __clock（そのデータの最大同期時刻）を持たせ、クラウドを読むたびに自端末のオフセットを引き上げて「クラウドで見た最新より必ず新しい時刻」を刻むようにした。これで端末の時計がずれていても後から行った入力が必ず勝つ。__clock を持たない既存データは記録の _savedAt 最大値から初期化。400日以上先の異常な時刻は取り込まない安全弁つき。あわせて _savedAt/_fieldTs/_updatedAt の刻印を全26箇所で新方式に統一。さらに、ローカル編集から20秒以上クラウド保存が成功していない場合は画面上部に「⚠ クラウドに保存できていません（N秒未同期）」＋「今すぐ再送」を常時表示し、同期停止が無表示のまま続かないようにした。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">18fda72</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"ケアマネ連携\" data-text=\"事業所の更新をケアマネへ通知：変更項目名の明示と保険証内容変更の追加フェイスシート更新の通知が「フェイスシート」としか出ず、どこを変えたか分からなかった。また介護保険証・負担割合証は「添付ファイルの更新」しか通知されず、要介護度や負担割合の内容変更はケアマネに届かなかった。新旧フェイスシートを項目単位で差分比較する difffacesheetfields を追加し「フェイスシート（服薬状況・通所の経緯）」のように変更項目名を表示（最大8件＋ほかn項目）。利用者マスタで要介護度／認定有効期間／負担割合を変更した際も、ケアマネにのみ未読通知（by=office / readcm=false）を発行。逆方向（ケアマネの編集→事業所ホーム「家族・ケアマネからの更新」）も項目名を表示。ケアマネ連携cdecfc6\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">ケアマネ連携</span><span class=\"date tnum\">2026-07-20</span></div>\n      <p class=\"title\">事業所の更新をケアマネへ通知：変更項目名の明示と保険証内容変更の追加</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フェイスシート更新の通知が「フェイスシート」としか出ず、どこを変えたか分からなかった。また介護保険証・負担割合証は「添付ファイルの更新」しか通知されず、要介護度や負担割合の内容変更はケアマネに届かなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>新旧フェイスシートを項目単位で差分比較する diffFaceSheetFields を追加し「フェイスシート（服薬状況・通所の経緯）」のように変更項目名を表示（最大8件＋ほかN項目）。利用者マスタで要介護度／認定有効期間／負担割合を変更した際も、ケアマネにのみ未読通知（by=office / readCm=false）を発行。逆方向（ケアマネの編集→事業所ホーム「家族・ケアマネからの更新」）も項目名を表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">cdecfc6</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"計画書\" data-text=\"計画書4様式に一時保存を統一・残りの日付欄もカレンダー化一時保存が通所計画書のみで、個別機能訓練・生活機能チェック・興味関心は途中保存できず、一部の日付が手入力のままだった。4様式すべてに「一時保存／保存して閉じる」を追加。発症日・入院日・退院日・作成日等もカレンダー選択に統一。計画書98add01\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-18</span></div>\n      <p class=\"title\">計画書4様式に一時保存を統一・残りの日付欄もカレンダー化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">一時保存が通所計画書のみで、個別機能訓練・生活機能チェック・興味関心は途中保存できず、一部の日付が手入力のままだった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>4様式すべてに「一時保存／保存して閉じる」を追加。発症日・入院日・退院日・作成日等もカレンダー選択に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">98add01</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"利用者マスタ\" data-text=\"負担割合証：開始日を選び直したら常に1年後を終了日に設定「終了日が空のときだけ」1年後を計算していたため、開始日を選び直しても既存の終了日が更新されず、今日基準の古い値が残っていた。開始日を変えたら常に 終了日＝開始日＋1年−1日 を再設定。うるう年含め検証。利用者マスタe8cb276\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-18</span></div>\n      <p class=\"title\">負担割合証：開始日を選び直したら常に1年後を終了日に設定</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">「終了日が空のときだけ」1年後を計算していたため、開始日を選び直しても既存の終了日が更新されず、今日基準の古い値が残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>開始日を変えたら常に 終了日＝開始日＋1年−1日 を再設定。うるう年含め検証。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e8cb276</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"計画書\" data-text=\"通所介護計画書：日付のカレンダー選択・一時保存・目標期間の逆コピー日付が手入力のみ、途中保存ができず、期間コピーの向きが実務と逆だった。作成日・目標・提供内容①〜⑤等をカレンダー選択に。一時保存を追加。長期目標の期間を①〜⑤へ下ろすコピーに変更。計画書86d5926\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-18</span></div>\n      <p class=\"title\">通所介護計画書：日付のカレンダー選択・一時保存・目標期間の逆コピー</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">日付が手入力のみ、途中保存ができず、期間コピーの向きが実務と逆だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>作成日・目標・提供内容①〜⑤等をカレンダー選択に。一時保存を追加。長期目標の期間を①〜⑤へ下ろすコピーに変更。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">86d5926</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"LIFE加算\" data-text=\"生活機能チェックのadlからbarthel点数を提案同じ10項目を生活機能チェックとbarthelで二度入力していた。生活機能チェックのadl→barthel点数の対応表を作り、取り込みボタンで自動提案（最終確認は職員）。life加算c1c5f93\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">LIFE加算</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">生活機能チェックのADLからBarthel点数を提案</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">同じ10項目を生活機能チェックとBarthelで二度入力していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>生活機能チェックのADL→Barthel点数の対応表を作り、取り込みボタンで自動提案（最終確認は職員）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c1c5f93</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"計画書\" data-text=\"生活機能チェック：項目名とプルダウンの間隔・幅を調整ラベルが固定幅でプルダウンが伸び、隣の項目とくっついて読みにくかった。項目名にプルダウンを寄せ、幅を縮小し、列間を広げた。計画書193774f\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">生活機能チェック：項目名とプルダウンの間隔・幅を調整</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ラベルが固定幅でプルダウンが伸び、隣の項目とくっついて読みにくかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>項目名にプルダウンを寄せ、幅を縮小し、列間を広げた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">193774f</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"計画書\" data-text=\"計画書：フェイスシート連携の参照先を修正・自動作成を廃止・1日の流れ/提供区分を自動化フェイスシートの保存先を取り違え、連携が丸ごと不動だった（自立度が入らない等）。利用者追加時に空の計画書が自動作成されていた。正しい保存先を参照。自動作成を廃止。1日の流れ（am/pm両方）と提供時間区分を自動算出。計画書700fe4a\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">計画書：フェイスシート連携の参照先を修正・自動作成を廃止・1日の流れ/提供区分を自動化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">フェイスシートの保存先を取り違え、連携が丸ごと不動だった（自立度が入らない等）。利用者追加時に空の計画書が自動作成されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>正しい保存先を参照。自動作成を廃止。1日の流れ（AM/PM両方）と提供時間区分を自動算出。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">700fe4a</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"連絡帳\" data-text=\"連絡帳：反映元の「未選択」を廃止し、無効なら先頭項目に連動連動を選んでも未選択では自由記述と変わらず無意味だった。未選択という状態をなくし、無効なら先頭の運動項目に自動連動。表示と実挙動を一致させた。連絡帳7344829\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">連絡帳：反映元の「未選択」を廃止し、無効なら先頭項目に連動</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">連動を選んでも未選択では自由記述と変わらず無意味だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>未選択という状態をなくし、無効なら先頭の運動項目に自動連動。表示と実挙動を一致させた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">7344829</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"連絡帳\" data-text=\"連絡帳：反映元が未設定でも設定済みに見える問題を修正選択肢に空欄が無く、連動先が無効でもブラウザが先頭項目を表示。設定済みに見えて実際は連動しなかった。無効な連動先を検知し、名前一致でも値を拾えるよう解決規則を統一。連絡帳45c32c8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">連絡帳：反映元が未設定でも設定済みに見える問題を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">選択肢に空欄が無く、連動先が無効でもブラウザが先頭項目を表示。設定済みに見えて実際は連動しなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>無効な連動先を検知し、名前一致でも値を拾えるよう解決規則を統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">45c32c8</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"分析\" data-text=\"分析個人：○の規定値を「月初」でなく記録の実日付で引く規定値を月の1日時点で引いていたため、月途中に設定した規定値が反映されず、店舗差になっていた。記録の実日付で規定値を引くよう修正。設定タイミングに関わらず反映。分析c5df252\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○の規定値を「月初」でなく記録の実日付で引く</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">規定値を月の1日時点で引いていたため、月途中に設定した規定値が反映されず、店舗差になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>記録の実日付で規定値を引くよう修正。設定タイミングに関わらず反映。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c5df252</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"分析\" data-text=\"分析個人：○で規定値をグラフに反映・個別運動は選択した種目名で表示規定値の取得がid直接一致のみで、項目を作り直した店舗で取れなかった。個別運動が「個別運動①」表示だった。id一致→同名で解決。個別運動は選択した種目名（屋外歩行訓練等）で表示。分析c300df8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○で規定値をグラフに反映・個別運動は選択した種目名で表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">規定値の取得がid直接一致のみで、項目を作り直した店舗で取れなかった。個別運動が「個別運動①」表示だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>id一致→同名で解決。個別運動は選択した種目名（屋外歩行訓練等）で表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">c300df8</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"提供記録\" data-text=\"提供記録入力：規定値がセルに収まるようフォントを縮小文字サイズを入力値の長さだけで決め、規定値だけ表示の空セルで長い値がはみ出していた。規定値の長さも考慮してフォントサイズを決定。提供記録ac31e0d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">提供記録入力：規定値がセルに収まるようフォントを縮小</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">文字サイズを入力値の長さだけで決め、規定値だけ表示の空セルで長い値がはみ出していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>規定値の長さも考慮してフォントサイズを決定。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ac31e0d</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"分析\" data-text=\"分析個人：○は規定値を反映・個別運動の規定値ルックアップを修正○に単位が付き「○分」と表示。個別運動の規定値を持たない側を先に見て常に空だった。記号に単位を付けない。個別運動は利用者側の規定値を優先（3箇所修正）。分析9526174\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○は規定値を反映・個別運動の規定値ルックアップを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">○に単位が付き「○分」と表示。個別運動の規定値を持たない側を先に見て常に空だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>記号に単位を付けない。個別運動は利用者側の規定値を優先（3箇所修正）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9526174</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"分析\" data-text=\"店舗によって運動の○が分析個人に反映されない不具合を修正分析個人がid直接一致でしか値を引かず、項目を作り直した店舗だけ「記録なし」になっていた。idが変わっても同名で拾う解決関数に統一。分析add9d88\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">店舗によって運動の○が分析個人に反映されない不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">分析個人がid直接一致でしか値を引かず、項目を作り直した店舗だけ「記録なし」になっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>idが変わっても同名で拾う解決関数に統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">add9d88</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"分析\" data-text=\"分析個人：○(実施)の記録が規定値未設定の月に消える不具合を修正○を規定値に置換する際、規定値が未設定の月は空を返し、実施記録が「記録なし」扱いになっていた。規定値が無くても○のまま残す。分析ffcf5d6\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">分析個人：○(実施)の記録が規定値未設定の月に消える不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">○を規定値に置換する際、規定値が未設定の月は空を返し、実施記録が「記録なし」扱いになっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>規定値が無くても○のまま残す。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">ffcf5d6</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"分析\" data-text=\"体力測定グラフ：最低のフォントを揃え、開始位置の右寄りを直す最低のラベルだけ極端に小さく、1件時にグラフ開始点が大きく右へずれていた。体温グラフと同じ体裁に統一し、固定ステップ＋左パディング方式に。分析9b76c39\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">体力測定グラフ：最低のフォントを揃え、開始位置の右寄りを直す</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">最低のラベルだけ極端に小さく、1件時にグラフ開始点が大きく右へずれていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>体温グラフと同じ体裁に統一し、固定ステップ＋左パディング方式に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9b76c39</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"体力測定\" data-text=\"体力測定：タップでテンキー表示・全角入力を半角へ自動変換身長体重等の数値入力でテンキーが出ず、全角入力すると値が消えることがあった。提供記録と同じテンキーを表示。全角数字・句読点を半角へ自動変換。体力測定41549bc\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">体力測定</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">体力測定：タップでテンキー表示・全角入力を半角へ自動変換</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">身長体重等の数値入力でテンキーが出ず、全角入力すると値が消えることがあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>提供記録と同じテンキーを表示。全角数字・句読点を半角へ自動変換。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">41549bc</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"利用者マスタ\" data-text=\"利用者マスタの電話番号（固定/携帯）に自動でハイフンを付与既存フォーマッタから漏れ、全角入力で番号が消える不具合もあった。共通フォーマッタに統一し、全角対応も追加。12ケースで検証。利用者マスタ50aa40b\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">利用者マスタの電話番号（固定/携帯）に自動でハイフンを付与</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">既存フォーマッタから漏れ、全角入力で番号が消える不具合もあった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>共通フォーマッタに統一し、全角対応も追加。12ケースで検証。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">50aa40b</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"計画書\" data-text=\"作成予定をホームからサイドバー「計画書 &gt; 作成予定」へ移動導入直後は全員が未作成で件数が膨らみ、ホームで実用にならなかった。専用画面に移動。未作成は既定で隠し、必要時に表示できるように。計画書b6ec8b9\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">作成予定をホームからサイドバー「計画書 &gt; 作成予定」へ移動</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">導入直後は全員が未作成で件数が膨らみ、ホームで実用にならなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>専用画面に移動。未作成は既定で隠し、必要時に表示できるように。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b6ec8b9</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"計画書\" data-text=\"計画書・加算の作成時期を通知作成期限の把握手段がなく、作成漏れが起きやすかった。期限の1ヶ月前から、誰の・何を・いつまでにを月ごとに表示。計画書f86b363\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">計画書・加算の作成時期を通知</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">作成期限の把握手段がなく、作成漏れが起きやすかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>期限の1ヶ月前から、誰の・何を・いつまでにを月ごとに表示。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">f86b363</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"計画書\" data-text=\"共通項目の連携：自立度をフェイスシート起点に統一自立度が3画面で別名保存され、半角/全角の違いで○が付かなかった。表記ゆれを吸収し、フェイスシートを正として各計画書へ取り込み。計画書67e213a\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">共通項目の連携：自立度をフェイスシート起点に統一</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">自立度が3画面で別名保存され、半角/全角の違いで○が付かなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>表記ゆれを吸収し、フェイスシートを正として各計画書へ取り込み。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">67e213a</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"計画書\" data-text=\"個別機能訓練計画書（様式3-3）をa4 1枚で使い切る高さ指定がなく下部に余白が残っていた。a4実寸の縦フレックスにし、各記入欄を比率配分。計画書eb4f153\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-17</span></div>\n      <p class=\"title\">個別機能訓練計画書（様式3-3）をA4 1枚で使い切る</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">高さ指定がなく下部に余白が残っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>A4実寸の縦フレックスにし、各記入欄を比率配分。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eb4f153</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"提供記録\" data-text=\"月モードの保存で他の月の記録が全て消えるバグを修正選択月のみ保持する配列で全記録を置換しており、保存で他月が失われる構造だった（未使用画面／予防）。id単位のマージに変更し、選択月以外を必ず温存。提供記録dc4a6c0\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">提供記録</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">月モードの保存で他の月の記録が全て消えるバグを修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">選択月のみ保持する配列で全記録を置換しており、保存で他月が失われる構造だった（未使用画面／予防）。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>id単位のマージに変更し、選択月以外を必ず温存。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">dc4a6c0</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"提供記録\" data-text=\"検索一覧の表示を提供記録入力に完全に合わせる色・脈表記・介護整体列が入力画面と揃っていなかった。状態色・脈（）表記・介護整体列を入力画面と統一。提供記録61bb967\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">検索一覧の表示を提供記録入力に完全に合わせる</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">色・脈表記・介護整体列が入力画面と揃っていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>状態色・脈（）表記・介護整体列を入力画面と統一。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">61bb967</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"提供記録\" data-text=\"氏名検索の月一覧を提供記録入力と同じ表形式に検索結果がテキスト一覧で入力画面と見え方が違った。同じ列構成の表にし、行タップで当日入力へジャンプ。提供記録02e699d\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">氏名検索の月一覧を提供記録入力と同じ表形式に</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">検索結果がテキスト一覧で入力画面と見え方が違った。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>同じ列構成の表にし、行タップで当日入力へジャンプ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">02e699d</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"家族アプリ\" data-text=\"分析個人の公開範囲：モニタリングはケアマネのみ・特記は本人に非表示ナイーブな臨床所見が本人・家族に見えていた。モニタリングはケアマネ限定、今回の様子・特記は本人に非表示（家族は可）。家族アプリ9b642fa\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">家族アプリ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">分析個人の公開範囲：モニタリングはケアマネのみ・特記は本人に非表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">ナイーブな臨床所見が本人・家族に見えていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>モニタリングはケアマネ限定、今回の様子・特記は本人に非表示（家族は可）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">9b642fa</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"提供記録\" data-text=\"氏名検索一覧に運動の数値も表示状態・バイタルのみで運動が確認できなかった。各運動項目の記録値を一覧に追加。提供記録35874fe\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">氏名検索一覧に運動の数値も表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">状態・バイタルのみで運動が確認できなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>各運動項目の記録値を一覧に追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">35874fe</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"提供記録\" data-text=\"提供記録入力：氏名検索でその月の利用日を全て表示検索しても当日のロスターしか出ず、来所しない人は表示されなかった。その月の利用日を一覧化し、行タップで当日入力へ。提供記録34725e7\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">提供記録</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">提供記録入力：氏名検索でその月の利用日を全て表示</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">検索しても当日のロスターしか出ず、来所しない人は表示されなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>その月の利用日を一覧化し、行タップで当日入力へ。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">34725e7</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"分析\" data-text=\"欠席理由ランキング：振替側に後から書いた理由も拾う欠席側にしか理由を見に行かず、振替側に追記した理由が集計に反映されなかった。対の振替側レコードの理由も拾って集計。分析10e2b70\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">欠席理由ランキング：振替側に後から書いた理由も拾う</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">欠席側にしか理由を見に行かず、振替側に追記した理由が集計に反映されなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>対の振替側レコードの理由も拾って集計。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">10e2b70</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"分析\" data-text=\"欠席理由ランキング：振替の日付表記でなく実際の理由で集計振替の欠席理由が「○月○日へ振替」の文字列丸ごとで集計され、日付が理由として並んでいた。括弧内の実際の理由で集計し、語尾ゆらぎもまとめた。分析bb991c2\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">分析</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">欠席理由ランキング：振替の日付表記でなく実際の理由で集計</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">振替の欠席理由が「○月○日へ振替」の文字列丸ごとで集計され、日付が理由として並んでいた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>括弧内の実際の理由で集計し、語尾ゆらぎもまとめた。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bb991c2</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"管理局\" data-text=\"管理局から設定したアドオンが巻き戻る不具合を修正読んでから書く構造で連続操作が消え、項目単位の時刻更新も無く店舗端末の保存で巻き戻っていた。cas（楽観ロック）内で完結させ、時刻も更新。管理局a1792d3\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">管理局</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">管理局から設定したアドオンが巻き戻る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">読んでから書く構造で連続操作が消え、項目単位の時刻更新も無く店舗端末の保存で巻き戻っていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>CAS（楽観ロック）内で完結させ、時刻も更新。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">a1792d3</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"各種設定\" data-text=\"単位欄の既定値を廃止し、例示が見切れないよう幅を拡大個別運動の追加行に既定値『回』が入り、単位の違う種目でも残っていた。例示も見切れていた。既定値を廃止して例示表示に。入力欄の幅を拡大。各種設定99bc709\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">各種設定</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">単位欄の既定値を廃止し、例示が見切れないよう幅を拡大</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">個別運動の追加行に既定値『回』が入り、単位の違う種目でも残っていた。例示も見切れていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>既定値を廃止して例示表示に。入力欄の幅を拡大。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">99bc709</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"同期\" data-text=\"提供記録は空欄なのに連絡帳に古いバイタルが出る不具合を修正派生値（プレーンのバイタル）を独立にマージし、非空優先のため一度入った値が消せなかった。マージ後にam/pmから射影し直し、空欄なら空欄に。同期5f906e8\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">提供記録は空欄なのに連絡帳に古いバイタルが出る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">派生値（プレーンのバイタル）を独立にマージし、非空優先のため一度入った値が消せなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>マージ後にAM/PMから射影し直し、空欄なら空欄に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5f906e8</span></span></div>\n    </article>\n<article class=\"row k-imp\" data-kind=\"imp\" data-area=\"利用者マスタ\" data-text=\"認定有効期間だけの更新も変更履歴に残す値が同じで期間だけ更新した場合が履歴に残らなかった。開始日が変われば「認定更新」として履歴に記録（3経路統一）。利用者マスタeea97e5\">\n      <div class=\"row-top\"><span class=\"tag k-imp\">改善</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">認定有効期間だけの更新も変更履歴に残す</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">値が同じで期間だけ更新した場合が履歴に残らなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>開始日が変われば「認定更新」として履歴に記録（3経路統一）。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">eea97e5</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"同期\" data-text=\"書類削除を1回で確定・次回予定は編集した項目だけ保存書類削除がpullで復活。次回予定は全員分の計算値が書き込まれ全員が変更済みになっていた。個人ファイル表示中はpull停止＋墓石尊重。次回予定は変更項目のみ保存。同期b4a3a62\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">書類削除を1回で確定・次回予定は編集した項目だけ保存</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">書類削除がpullで復活。次回予定は全員分の計算値が書き込まれ全員が変更済みになっていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>個人ファイル表示中はpull停止＋墓石尊重。次回予定は変更項目のみ保存。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b4a3a62</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"連絡帳\" data-text=\"連絡帳の次回予定：欠席の日を飛ばし振替を優先月間シフトのみ見て提供記録の欠席を見ておらず、欠席日のまま表示されていた。提供記録を優先し、欠席は飛ばし振替を優先。連絡帳bffc945\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">連絡帳</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">連絡帳の次回予定：欠席の日を飛ばし振替を優先</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">月間シフトのみ見て提供記録の欠席を見ておらず、欠席日のまま表示されていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>提供記録を優先し、欠席は飛ばし振替を優先。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">bffc945</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"同期\" data-text=\"各種設定の変更が4秒後に巻き戻る不具合を修正クラウド取得（pull）が丸ごと置換で、保存完了前の4秒ポーリングが古い値で上書きしていた。設定を項目単位の時刻で保持し、他端末の変更は潰さない。同期b907b77\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">各種設定の変更が4秒後に巻き戻る不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">クラウド取得（pull）が丸ごと置換で、保存完了前の4秒ポーリングが古い値で上書きしていた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>設定を項目単位の時刻で保持し、他端末の変更は潰さない。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">b907b77</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"利用者マスタ\" data-text=\"変更履歴タブが開けないエラーを修正（info is not defined）アイコンを未importで使用し、タブを開くと画面全体がエラーになった。import済みアイコンに差し替え。全jsxの未importを機械検査。利用者マスタ5f48438\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">変更履歴タブが開けないエラーを修正（Info is not defined）</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">アイコンを未importで使用し、タブを開くと画面全体がエラーになった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>import済みアイコンに差し替え。全JSXの未importを機械検査。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">5f48438</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"利用者マスタ\" data-text=\"介護度/負担割合/ケアマネの変更履歴を入力1か所から自動記録直接編集しても変更履歴・支援経過表に反映されず、二重入力が同期漏れの温床だった。入力起点を基本情報に統一し、履歴と支援経過表へ自動記録。利用者マスタe8fe1de\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">利用者マスタ</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">介護度/負担割合/ケアマネの変更履歴を入力1か所から自動記録</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">直接編集しても変更履歴・支援経過表に反映されず、二重入力が同期漏れの温床だった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>入力起点を基本情報に統一し、履歴と支援経過表へ自動記録。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e8fe1de</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"同期\" data-text=\"書類（保険証/負担割合証）の削除が復活する不具合を修正id単位の和集合マージで削除が表現できず、クラウドの残存で必ず復活していた。墓石（削除記録）を導入し、両端末で合算して復活を防止。同期3843f08\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">同期</span><span class=\"crit\">重大</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">書類（保険証/負担割合証）の削除が復活する不具合を修正</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">id単位の和集合マージで削除が表現できず、クラウドの残存で必ず復活していた。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>墓石（削除記録）を導入し、両端末で合算して復活を防止。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">3843f08</span></span></div>\n    </article>\n<article class=\"row k-bug\" data-kind=\"bug\" data-area=\"計画書\" data-text=\"通所介護計画書：印刷の行高さ・列幅を修正、入力を自動化セル書式のpre-wrapで改行が余白として描画され行が異常に高く、列幅指定も効いていなかった。書式を分離し、colgroupで列幅を効かせ、入力の自動化を追加。計画書75dbd58\">\n      <div class=\"row-top\"><span class=\"tag k-bug\">バグ修正</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">通所介護計画書：印刷の行高さ・列幅を修正、入力を自動化</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">セル書式のpre-wrapで改行が余白として描画され行が異常に高く、列幅指定も効いていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>書式を分離し、colgroupで列幅を効かせ、入力の自動化を追加。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">75dbd58</span></span></div>\n    </article>\n<article class=\"row k-feat\" data-kind=\"feat\" data-area=\"計画書\" data-text=\"通所介護計画書を厚労省 別紙様式3-4 準拠に刷新独自レイアウトで公的様式と構造が違い、a4に収まっていなかった。別紙様式3-4準拠に作り直し、a4 1枚で使い切る構成に。計画書e60fc54\">\n      <div class=\"row-top\"><span class=\"tag k-feat\">機能追加</span><span class=\"area\">計画書</span><span class=\"date tnum\">2026-07-16</span></div>\n      <p class=\"title\">通所介護計画書を厚労省 別紙様式3-4 準拠に刷新</p>\n      <div class=\"cf\"><span class=\"lb\">原因</span><span class=\"tx\">独自レイアウトで公的様式と構造が違い、A4に収まっていなかった。</span><span class=\"lb\">対応</span><span class=\"tx\"><b>別紙様式3-4準拠に作り直し、A4 1枚で使い切る構成に。</b></span><span class=\"lb\">記録</span><span class=\"tx\"><span class=\"cid\">e60fc54</span></span></div>\n    </article>\n  </div>\n  <section class=\"block\"><h2>未対応・今後の予定</h2><p class=\"lead\">まだ着手していない、または継続中の項目です。優先度は事業インパクト順。</p><div class=\"todo\" id=\"todo\">\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>操作ログ同期の第2段（受信適用と旧方式の凍結）</b><span>現在は第1段＝「送信のみ」。診断ログで ops-queued→ops-acked が安定して出ることを確認できたら、OPLOG_APPLY と OPLOG_FROZEN_KEYS を有効にして切替を完了する。その後フェーズ5（DB側での操作ログ畳み込みと刈り取り）を追加する。</span></div><span class=\"prio\">優先度：最優先</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>認証基盤の是正（Supabase Auth 未使用）</b><span>職員ログインが staff テーブルへのSELECT照合のみでJWTを発行しておらず、全アクセスがanonロール。anon keyはJSバンドルから誰でも取得できるため、RLSを書いても店舗ごとの分離をDB側で強制できない。介護記録は要配慮個人情報にあたるため、同期刷新の完了後に着手する（放置ではなく延期）。</span></div><span class=\"prio\">優先度：高（同期刷新の次）</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>実績記録票のCSV出力 → 格安/無料の請求ソフトへ連携</b><span>収益に最短で効く本命。連携先ソフトのCSV形式が分かれば着手可能。</span></div><span class=\"prio\">優先度：最優先</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>国保連請求データのCSV生成</b><span>介護給付費請求書等インターフェース仕様書（最新版）に準拠して生成。テスト伝送での検証が必須。</span></div><span class=\"prio\">優先度：高</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>LIFE加算のCSV出力・提出</b><span>LIFEの公式CSV連携仕様に沿って出力。実データでのアップロード検証が必要。</span></div><span class=\"prio\">優先度：高</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>モニタリング自動FAX（丸投げ君 代替）の仕上げ</b><span>FAX API・モニタリング表は実装済み。運用の詰めを残す。</span></div><span class=\"prio\">優先度：中</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>ケアプラン写真/PDFの取り込み → 計画書へ転記</b><span>OCR/貼り付けで目標以外の転記を省力化する構想。</span></div><span class=\"prio\">優先度：中</span></div>\n  <div class=\"titem\"><span class=\"st hold\">構想</span><div class=\"body\"><b>勤務表を日誌データから自動作成</b><span>手入力に加え、日誌の出勤・送迎・記録者から実績を自動生成。</span></div><span class=\"prio\">優先度：低</span></div>\n  <div class=\"titem\"><span class=\"st plan\">予定</span><div class=\"body\"><b>計画書の残作業（個別3-3のカレンダー化 等）</b><span>通所で入れた一時保存・カレンダーを個別機能訓練計画書にも展開。</span></div><span class=\"prio\">優先度：中</span></div>\n    </div></section>\n  <section class=\"block\"><h2>請求・LIFE実装に必要な資料</h2><p class=\"lead\">実績→請求／LIFE加算の実装を正確に進めるために、そろえていただきたい資料です。</p><div class=\"docs\" id=\"docs\">\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">1</span>介護給付費請求 CSVインターフェース仕様書</p><ul><li>国保中央会が定める請求データの公式仕様（最新版）</li><li>明細書・給付管理票のレコード様式</li><li>エラーコード一覧</li></ul><p class=\"note\">これがあれば「つむぎのどのデータをどう並べるか」を具体設計できます。</p></div>\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">2</span>LIFE CSV連携仕様書</p><ul><li>厚労省/LIFEが公開するCSVレイアウト</li><li>科学的介護推進・個別機能訓練加算 の項目定義</li><li>コード表（評価区分・選択肢の数値）</li></ul><p class=\"note\">LIFEは細部が厳格。実データでのアップロード検証を前提に。</p></div>\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">3</span>現行ソフトの出力サンプル</p><ul><li>カイポケ：実績記録票・請求明細書・給付管理票のPDF</li><li>マルットライフ：LIFE提出用CSV/PDF</li><li>丸投げ君：モニタリングFAXの送信様式</li></ul><p class=\"note\">項目を合わせる基準になります。個人情報は伏せた見本で十分です。</p></div>\n  <div class=\"doc\"><p class=\"h\"><span class=\"n\">4</span>連携先の請求ソフト情報</p><ul><li>採用予定の格安/無料 請求ソフト名</li><li>そのソフトが取り込めるCSVの形式・項目</li><li>（あれば）取り込みマニュアル</li></ul><p class=\"note\">連携先が決まればCSVをその形式に合わせて出力します。</p></div>\n    </div></section>\n  <footer>この台帳は開発時のコミット記録（Git）から生成しています。各行末尾の英数字はコミットIDで、変更内容の実体と1対1で対応します。「重大」はデータの消失・巻き戻りに関わる不具合です。</footer>\n</div>\n<script>\n(function(){try{\n  var rows=[].slice.call(document.querySelectorAll('#ledger .row')),cl=document.getElementById('count-line'),st={kind:'all',area:'all',q:''};\n  function apply(){var n=0;rows.forEach(function(r){var ok=(st.kind==='all'||r.getAttribute('data-kind')===st.kind)&&(st.area==='all'||r.getAttribute('data-area')===st.area)&&(st.q===''||(r.getAttribute('data-text')||'').indexOf(st.q)>=0);r.style.display=ok?'':'none';if(ok)n++;});if(cl)cl.textContent='表示 '+n+' 件 ／ 全 '+rows.length+' 件';}\n  var kc=document.getElementById('kind-chips');kc&&kc.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-kind]');if(!b)return;st.kind=b.getAttribute('data-kind');[].forEach.call(kc.children,function(c){c.setAttribute('aria-pressed',c===b?'true':'false');});apply();});\n  var ac=document.getElementById('area-chips');ac&&ac.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-area]');if(!b)return;st.area=b.getAttribute('data-area');[].forEach.call(ac.children,function(c){c.setAttribute('aria-pressed',c===b?'true':'false');});apply();});\n  var q=document.getElementById('q');q&&q.addEventListener('input',function(e){st.q=(e.target.value||'').toLowerCase();apply();});\n}catch(err){}})();\n</script>\n\n</body>\n</html>\n";
export default function handler(req, res) {
  const USER = process.env.CHANGELOG_USER || 'tsumugi';
  const PASS = process.env.CHANGELOG_PASS || 'hennkoukiroku';
  const h = req.headers.authorization || '';
  let ok = false;
  if (h.startsWith('Basic ')) { try { const dec = Buffer.from(h.slice(6),'base64').toString('utf8'); const i = dec.indexOf(':'); if (i!==-1 && dec.slice(0,i)===USER && dec.slice(i+1)===PASS) ok=true; } catch(e){} }
  if (!ok) { res.setHeader('WWW-Authenticate','Basic realm="tsumugi", charset="UTF-8"'); res.setHeader('content-type','text/plain; charset=utf-8'); res.status(401).send('認証が必要です / Authentication required'); return; }
  res.setHeader('content-type','text/html; charset=utf-8'); res.setHeader('cache-control','no-store'); res.setHeader('x-robots-tag','noindex, nofollow, noarchive'); res.status(200).send(HTML);
}
